// src/shared/skill-fallbacks.generated.ts
// GENERATED FILE — do not edit. Regenerate with:
//   npx tsx src/build/gen-skill-fallbacks.ts
// `npm run plugin:check` fails when this file and the SKILL.md bodies disagree.
//
// The body of every `T1BLOCK` that ships, keyed `<moduleId> :: <blockName>`.
// shared/skill-block.ts consults it when a module's SKILL.md cannot be read, so
// a gate whose prose file is missing from the install still refuses IN WORDS.
//
// DO NOT "simplify" this away by deleting the table and trusting the SKILL.md
// read. That read is rooted at `pluginRoot()`, an environment-supplied path
// that never refuses an unverified root; this module is resolved by Node
// relative to the file that imports it, so it is reachable on precisely the
// torn install the fallback exists for. Deleting it turns a drift bug into a
// silent-deny bug, and no build-time check can catch that, because the failure
// is in the environment and not in the tree.

export const SKILL_FALLBACKS: Readonly<Record<string, string>> = {
  "agent-model :: absolute-traffic-one-path": "Spawn prompt path gate: the prompt references `.traffic-one` run/digest/fix-cycle paths outside this project root (`{{PROJECT_ROOT}}`): {{BAD_PATHS}}. Re-issue the same spawn using project-relative paths such as `.traffic-one/digests/<runId>/frontend.md` and `.traffic-one/fix-cycles/<runId>/senior-frontend-fix-1.md` (digest files use the short role name; fix-cycle files keep the full `senior-` prefix); do not paste absolute paths from another folder or a corrupted root.",
  "agent-model :: agent-activity-exploration-cap": "traffic-one — exploration cap: `{{ROLE}}` has made {{COUNT}} tool calls in run `{{RUN_ID}}` and this search/read call is refused ONCE as a consolidation checkpoint (editing, shell verification, and digest writes are never blocked, and every later call — including search/read — goes through). Write down what you already know, then act on it: batch the remaining related reads, group coherent edits, run ONE combined verification command per surface, do not re-read rules or files already loaded, and finish the assignment before exploring further. Cap: {{CAP}} calls per child (config `agentActivity.explorationCap`, env `T1_EXPLORATION_CAP`; 0 disables).",
  "agent-model :: agent-materialization-deny": "Traffic One agent spawn gate: state was repaired/materialized before this agent spawn.\nThe role agent has been denied once so frontend/backend workers cannot start against stale `.traffic-one/.one.json`, rules, skills, or root agent context.\nrerun the same agent spawn now; the canonical `.traffic-one/.one.json` and project-local materialization are current.",
  "agent-model :: agent-materialization-missing": "Traffic One agent spawn gate: project-local rules/skills are not materialized yet.\nDo not spawn frontend/backend/reviewer/tester workers until `.traffic-one/.one.json` has current `materializedStack`, `materializedAt`, and `materializedVersion`, and `.traffic-one/manifest.json`, `.traffic-one/rules/**`, `.traffic-one/skills/**`, root `AGENTS.md`, and root `CLAUDE.md` exist.\nRun `node -e \"const p=require('node:path'),e=process.env,r=p.resolve(e.TRAFFIC_ONE_PLUGIN_ROOT||e.CURSOR_PLUGIN_ROOT||e.CODEX_PLUGIN_ROOT||e.CLAUDE_PLUGIN_ROOT||process.cwd());process.argv.splice(1,0,'traffic-one-runtime');require(p.join(r,'scripts','hook-runtime.cjs'))\" materialize-project` from the project root, then retry the agent spawn.{{CAUSE}}",
  "agent-model :: agent-reuse-await-codex-meta": "Agent-reuse gate: run {{RUN_ID}} has a fresh Codex `{{ROLE}}` registry row for child `{{AGENT_ID}}`, but Traffic One cannot verify that child's role from line-zero `session_meta` ({{REASON}}). Do not route `followup_task`/`send_message` to this unverified id and do not start a duplicate. Retry: {{REASON}} above names what is being waited on — a child rollout that has not flushed yet, or a registry row another process held while this hook ran — and both clear without your intervention. If the child is genuinely unusable, use `{{MARKER}}` with the concrete failure reason to retire it and spawn a replacement using the exact task-name contract (`quick_fix`, `senior_architect`, `senior_frontend`, `senior_backend`, `senior_reviewer`, `senior_tester`, or `senior_shipper`). Current Codex child rollouts encrypt spawn-message content, so prompt prose cannot substitute for `task_name` plus line-zero `session_meta` identity.",
  "agent-model :: agent-reuse-await-cursor-id": "Agent-reuse gate: `{{ROLE}}` is already running in this Cursor session. Resume that same Task — do not spawn another. If Task has no resume id yet, wait for the current one to finish, then continue it. Do not ask the user to switch to Low.",
  "agent-model :: agent-reuse-continue": "Agent-reuse gate: run {{RUN_ID}} already has a LIVE `{{ROLE}}` agent — id `{{AGENT_ID}}`. Do NOT spawn a fresh `{{ROLE}}`: every fresh spawn re-loads the full rules+skills context (~20k tokens before any work) and re-explores the codebase. Continue the SAME agent instead:\n1. {{CONTINUE_CALL}} The message carries ONLY what is NEW: the task spec, exact file paths, acceptance criteria, and (for fix cycles) the reviewer/tester findings VERBATIM. The agent keeps everything it already read — rules, skills, plan, digests, prior source — so do not re-paste any of that. On Cursor, `{{AGENT_ID}}` is the Task `resume` UUID from the spawn result (`Agent ID: …`), never the `tool_*` subagentStart id.\n2. Treat the reply exactly like a fresh spawn's final report (same digest + verdict-token contract: it must still end with its terminal token and update its digest under `.traffic-one/digests/<runId>/`).\n3. Parallel roles stay parallel: continuations of different roles (e.g. frontend + backend follow-ups) go out together in ONE turn, like parallel spawns.\n4. Only if that agent is genuinely unusable — {{CONTINUE_TOOL}} errors (\"agent not found\"/unavailable), or its replies show context exhaustion — re-spawn `{{ROLE}}` with the literal marker `{{MARKER}}` anywhere in the spawn prompt. The gate then allows ONE replacement spawn (same model-tier rules) and records the new agent id automatically.",
  "agent-model :: agent-reuse-scope-regrant": "Agent-reuse gate: run {{RUN_ID}} already has a LIVE `{{ROLE}}` agent — id `{{AGENT_ID}}` — so this second spawn was refused. Its `[t1-bounded-scope]` marker was NOT discarded: run {{RUN_ID}} has no compiled assignments, so for `{{ROLE}}` that marker is the ONLY origin of the bounded contract, and Traffic One republished it. `{{AGENT_ID}}` may now write exactly these {{FILE_COUNT}} file(s): {{FILES}}. The scope change is already in effect, so a second agent was never needed for it.\n1. {{CONTINUE_CALL}} The message carries ONLY what is NEW: the task spec, the exact file paths above, acceptance criteria, and (for fix cycles) the reviewer/tester findings VERBATIM. The agent keeps everything it already read.\n2. Treat the reply exactly like a fresh spawn's final report: the same digest + verdict-token contract, ending with its terminal token and updating `.traffic-one/digests/{{RUN_ID}}/{{ROLE}}.md`.\n3. Do NOT re-send this spawn to apply the same scope again — it is already published and an identical marker changes nothing. To widen it FURTHER, send one more spawn whose `[t1-bounded-scope]` line names the COMPLETE file set you want; each marker REPLACES the scope rather than adding to it. Only if `{{AGENT_ID}}` is genuinely unusable — {{CONTINUE_TOOL}} errors (\"agent not found\"/unavailable), or its replies show context exhaustion — re-spawn `{{ROLE}}` with the literal marker `{{MARKER}}` and that same scope line.",
  "agent-model :: agent-reuse-scope-regrant-refused": "Agent-reuse gate: run {{RUN_ID}} already has a LIVE `{{ROLE}}` agent — id `{{AGENT_ID}}` — so this second spawn was refused, and its `[t1-bounded-scope]` marker was refused with it. Traffic One could not republish `{{ROLE}}`'s WorkUnitContract, so the widening did NOT happen: `{{AGENT_ID}}` still holds the scope it started with, and the {{FILE_COUNT}} file(s) you asked for would be denied on every write — {{FILES}}. Do not continue as though the scope had changed.\n1. Re-send this SAME spawn once, unchanged. Publication reads the run's architecture snapshot, its host-capability sidecar and its bootstrap directory, and a concurrent hook holding any of those clears without your intervention.\n2. If the same refusal comes back, no scope change can be published for `{{ROLE}}` in run {{RUN_ID}} at all. Continue the live agent WITHIN THE SCOPE IT ALREADY HAS instead — {{CONTINUE_CALL}} — and give it only work its current contract covers.\n3. Do NOT reach for `{{MARKER}}`: replacing the agent destroys its context and publishes no contract either, so it cannot fix this. If the remaining work genuinely needs the wider scope and step 1 did not clear it, stop and report BLOCKED, quoting this message.",
  "agent-model :: architect-phase-incomplete": "Architect phase gate: `{{ROLE}}` cannot start yet — spawn `senior-architect` for run `{{RUN_ID}}` FIRST, in your next message. Do NOT retry `{{ROLE}}` unchanged and do NOT run the OpenCode Step-0 plan batch instead; neither clears this gate.\n\nMissing on disk: {{MISSING}}\n\nThe architect must finish the required project-memory baseline, semantic `.traffic-one/runs/{{RUN_ID}}/architecture-input-v1.json`, and `.traffic-one/digests/{{RUN_ID}}/architect.md` containing `PLAN_READY`. Traffic One runtime — not the architect — then compiles and atomically publishes architecture, verification, assignments, and work-unit bootstraps. Only after those hash-valid contracts exist may you retry `{{ROLE}}` with the same task. Do not spawn other implementers or patch runtime-owned coordination artifacts yourself.",
  "agent-model :: cursor-agent-type-required": "Cursor agent gate: `{{ROLE}}` was spawned with subagent_type `{{AGENT_TYPE}}`, which is neither the role's own Cursor agent nor the supported built-in fallback.\n\nRe-issue the same `Task` spawn with `subagent_type: \"{{EXPECTED_AGENT}}\"` — Traffic One materialized that role contract at `{{AGENT_PATH}}`.\n\nIf Cursor REJECTS that value (invalid enum / unknown subagent type), the agent files were written after this session captured its type list. That is NOT a broken spawn tool and NOT a reason to build the role inline: retry once with `subagent_type: \"{{FALLBACK_AGENT}}\"`, keep `[t1-role: {{ROLE}}]` as the FIRST line of the prompt, and immediately tell the child to read `{{AGENT_PATH}}` before acting. The role marker is what binds the child to its role and its frozen per-role model.\n\nKeep the exact per-role `model` from the spawn map either way. Never send a Traffic One role to a generic worker WITHOUT the role marker, and never simulate the role in the parent thread.",
  "agent-model :: cursor-api-limit-auto-retry": "Traffic One correlated `{{ROLE}}`'s Cursor child transcript to an API/usage-limit failure on **{{FAILED}}**. The failed agent is retired. Retry the same role now, without asking the user, on `model: \"{{NEXT}}\"` — the next exact captured slug from this role's original tier. Never announce or attempt a fallback named only by Cursor error prose. The next model is authoritative only when Traffic One supplies its exact slug. Issue the prescribed Task without a pre-tool model announcement, and do not say the replacement is running until a real `subagentStart` proves it.",
  "agent-model :: cursor-api-limit-composer-choice": "Traffic One correlated `{{ROLE}}`'s Cursor child transcript to an API/usage-limit failure. The next eligible model in this highest/balanced role's original tier is the Composer floor, so pause once for the user's choice:\n\n**enable** — Restore API budget for **{{RECOMMENDED}}**, then reply **enable**; I’ll retry on the recommended model.\n\n**fallback** — Proceed now on **{{FALLBACK}}**.\n\nDo not start Composer until the user replies **fallback**. A cheapest-tier role treats Composer as its normal tier model and rotates automatically to its next candidate instead of showing this downgrade choice.",
  "agent-model :: cursor-api-limit-terminal": "Traffic One model rotation is terminal for `{{ROLE}}` in this run: every eligible model that was actually started from the role's original tier reached an API/usage limit ({{TRIED}}). Stop retrying this role. The terminal marker remains after individual limit entries expire and clears only when the user replies **enable** or a new run starts; a model absent from Cursor's captured list never counts as API-limited.",
  "agent-model :: cursor-exact-model-required": "Cursor model gate (level={{LEVEL}}): spawning `{{ROLE}}` passed `model: \"{{PASSED}}\"`, which matches the right Traffic One tier family but is not an exact Cursor Task model id from the fresh captured list. Cursor can create a visible \"New subagent / Couldn't start\" card when Task receives an uncaptured model guess, so do NOT attempt the spawn with this value. Re-issue the same Task spawn with `model: \"{{EXPECTED}}\"` (or another exact captured id from the same tier). An exact captured id may equal its family anchor; membership in the captured list is authoritative. Captured ids for this build: {{CAPTURED}}.",
  "agent-model :: cursor-model-failure-generic": "Traffic One correlated `{{ROLE}}`'s Cursor child transcript to a non-API failure on **{{FAILED}}**. Use generic recovery and preserve the actual error; do not tell the user to enable a model. Authentication, network, user abort/cancel, context exhaustion, and generic API errors are not evidence that a model is disabled.",
  "agent-model :: cursor-model-unavailable-runtime-choice": "Traffic One correlated `{{ROLE}}`'s Cursor child transcript to an explicit model-unavailable failure for **{{FAILED}}**. This Settings prompt is valid only when the error text explicitly ties a model to “not enabled”, “disabled”, “unavailable”, “invalid”, “unsupported”, “unknown”, or “not found”.\n\n**enable** — Open Cursor Settings → Models, enable **{{FAILED}}**, then reply **enable**; I’ll retry on the recommended model.\n\n**fallback** — Proceed now on **{{FALLBACK}}**.\n\nDo not proceed until the user replies **enable** or **fallback**. The fallback is the next exact captured slug from this role's original tier.",
  "agent-model :: cursor-models-capture": "Cursor model-capture gate (required before the first team spawn, run {{RUN_ID}}). The spawn is blocked until Traffic One freezes the exact model ids offered by this Cursor build.\nMissing captured tiers for this run: {{MISSING_TIERS}}.\nDo this once before retrying:\n1. List the model ids your `Task` tool offers for spawning subagents (the same list Cursor shows when you pick a subagent model).\n2. Run `{{CAPTURE_CMD}}`, replacing the placeholders with those EXACT ids verbatim (e.g. `claude-fable-5-thinking-high`, `gpt-5.6-terra-medium`, `composer-2.5-fast`, or `gpt-5.4-mini`). A valid picker id may or may not include a reasoning suffix; never invent one. Include at least one id per tier the team needs — highest + balanced + cheapest. This internal command writes only your local per-user/project Cursor preferences; do not create `.traffic-one/cursor-models.json`.\n3. Re-run model-gate, then retry the spawn with the exact role→model value it prints. Project `.cursor/agents` contracts remain model-agnostic.\nDo not retry with an uncaptured family guess and do not build the project inline because of this gate.",
  "agent-model :: kilo-general-agent-required": "Kilo agent gate: `{{ROLE}}` must use Kilo's built-in writable Task subagent type `general`, not `{{AGENT_TYPE}}`.\n\nTraffic One materialized `{{AGENT_PATH}}` as the full role contract. This Kilo Task API exposes the built-in `general`/`explore` types, while `.kilo/agents/*.md` files are role-contract files rather than registered Task type names.\n\nRe-issue the same `task` spawn with `subagent_type: \"general\"`. Keep `[t1-role: {{ROLE}}]` as the FIRST line, immediately tell the child to read `{{AGENT_PATH}}` before acting, and omit `model` so it inherits the user's active Kilo model. Do NOT use `explore`, and do NOT fall back to main-agent mode: `general` is the supported Kilo subagent path for this role.",
  "agent-model :: model-availability-advisory": "Traffic One — this build will pass these exact Cursor models to its subagents: {{MODELS}}. A correlated API/usage-limit failure rotates automatically through the role's original tier; restore API budget to retry the recommended model, and a highest/balanced drop to the Composer floor requires an explicit **enable**/**fallback** choice. An explicit model-not-enabled/unavailable error offers Cursor Settings → Models or the next tier candidate. Authentication, network, abort/cancel, context exhaustion, and other generic failures use generic recovery and are never presented as a disabled model.",
  "agent-model :: model-availability-banner": "traffic-one — team models: {{MODELS}}. Correlated API limits rotate within each role's original tier; restore API budget for the recommended model, and Composer-floor downgrades require your explicit choice.",
  "agent-model :: model-choice-enable-required": "Model tier gate (level={{LEVEL}}, host={{HOST}}): the user chose **enable/retry**, so do NOT proceed on a fallback for `{{ROLE}}`. {{PASSED_NOTE}} Finish the selected remedy — restore API budget after an API-limit result, or enable/re-capture \"{{EXPECTED}}\" in Cursor Settings → Models after an availability result — then re-run the model-gate step and spawn with the recommended model. Do not advertise fallback alternates again for this build unless the user explicitly replies `fallback`.",
  "agent-model :: model-choice-recorded-enable": "Recorded: you'll retry on the recommended model. Traffic One cleared this run's API-limit ledger and pending model decisions. Re-run your request after completing the remedy you selected — restored API budget or Cursor Settings → Models — and the team will use the recommended model.",
  "agent-model :: model-choice-recorded-fallback": "Recorded: the team will use the next-eligible fallback model when the recommended one isn't available, for the rest of this build. Re-run your request to continue — I won't ask again this build.",
  "agent-model :: model-unavailable-choice": "Model availability gate (level={{LEVEL}}, host={{HOST}}): Cursor's fresh captured model list does not offer the recommended model **{{EXPECTED}}** for `{{ROLE}}`. Do not silently switch models.\n\n**enable** — Open Cursor Settings → Models, enable **{{EXPECTED}}**, then reply **enable**; I’ll retry on the recommended model.\n\n**fallback** — Proceed now on **{{FALLBACK}}**.\n\nDo not proceed until the user replies **enable** or **fallback**. The fallback is the next exact captured slug in this role's original tier; reaching the Composer floor for a highest/balanced role still requires this explicit choice.",
  "agent-model :: opencode-named-agent-required": "{{HOST}} agent gate: `{{ROLE}}` must be spawned with the project-scoped global {{HOST}} subagent `{{EXPECTED_AGENT}}`, not `{{AGENT_TYPE}}`.\n\nTraffic One materialized `{{AGENT_PATH}}`. {{MODEL_NOTE}}\n\nRe-issue the same `task` spawn with the project-scoped global subagent name `{{EXPECTED_AGENT}}` and keep `[t1-role: {{ROLE}}]` as the FIRST line of the prompt. Do NOT pass `model` unless this exact host build documents a Task `model` field. If `{{EXPECTED_AGENT}}` is not offered after materialization, stop and tell the user to restart {{HOST}} so the global agent at `{{AGENT_PATH}}` is loaded; do not fall back to `general` and do not build the role inline.",
  "agent-model :: opencode-plan-batch-required": "OpenCode plan-batch gate: do NOT spawn `{{ROLE}}` yet. The architect queued Step-0 OpenCode work in `.traffic-one/plan.md`, and the `opencode_delegate_from_plan` batch has not finished for queued role(s): {{QUEUED_ROLES}}.\n\nDo NOT retry Task/spawn_agent for any queued or capability-eligible implementer in this turn — run OpenCode Step 0 first instead.\n\nRun the batch FIRST, before any capability-eligible implementer starts:\n1. Call the `opencode_delegate_from_plan` tool (MCP server `opencode-worker`) with:\n   - `runId`: `{{RUN_ID}}`\n   - `projectRoot`: `{{PROJECT_ROOT}}`\n   Do NOT pass `model` unless the project explicitly pinned one; OpenCode selects its own free model by default.\n2. If it returns `running:true`, the batch worker keeps ITSELF alive in the background — your calls are not its keep-alive. Do useful work now (read digests, prepare the next phase), then collect the terminal `{ total, delegated, units }` in ONE bounded long wait: `opencode_status` with `{ runId, waitMs: 90000 }` (re-calling `opencode_delegate_from_plan` with the SAME arguments also waits). Do NOT use any shell fallback while `running:true`; to abandon the batch, call `opencode_status` with `{ runId, cancel: true }` — never just go silent.\n3. Only after the terminal result, spawn exactly the implementation roles present in the compiled capability profile and assignments manifest in the NEXT assistant message. Run multiple eligible roles in parallel; never invent a missing frontend/backend sibling. Pass each implementer the batch `units` summary, including `touched` files and any unit whose `action !== \"delegated\"` so the paid role finishes only what OpenCode skipped/failed/no-changed.\n4. Fail-open: if the batch returns a terminal failure (`ok:false`, `action: \"abandoned\"`, or every unit failed/skipped/no-changes) OR the MCP tool is unavailable, proceed with paid implementer spawns — do NOT block the build on OpenCode.\nFallback (MCP unavailable ONLY — never while `running:true`): `node ~/.traffic-one/bin/opencode-runner.cjs --run-id \"{{RUN_ID}}\" --from-plan` from `{{PROJECT_ROOT}}`.\n\nDo not work around this by spawning backend first, building inline, or using a whole-role `opencode_delegate` task. The Step-0 plan batch is what prevents serialized paid subagents and satisfies the OpenCode-first contract.",
  "agent-model :: opencode-role-delegate": "OpenCode role gate: `{{ROLE}}` is configured to run on OpenCode (it is in `openCode.delegateRoles` and `openCode.enabled` is true), so do NOT spawn it as a paid subagent yet. The user enabled this delegation in the Traffic One setup wizard. First hand its work to the locally-installed OpenCode CLI via the bundled `opencode-worker` MCP tool:\n1. Call the `opencode_delegate` tool (MCP server `opencode-worker`) with:\n   - `role`: `{{ROLE}}`\n   - `runId`: `{{RUN_ID}}`\n   - `projectRoot`: `{{PROJECT_ROOT}}`  (absolute path — the directory holding `.traffic-one`)\n   - `allowedFiles`: the exact comma-separated repo-relative files/areas this bounded unit may touch. Any diff outside this allowlist is rejected before apply.\n   - `task`: ONE bounded unit for this role — 1–2 named files with concrete acceptance criteria. NEVER the entire role implementation: free models deliver a bounded unit in ~2 minutes but produce nothing useful from a whole-role dump (measured live: zero output after minutes of serialized waiting). If the architect's plan queued units for this role, run the Step-0 `opencode_delegate_from_plan` batch instead — completing it marks every queued role as attempted and satisfies this gate.\n   Do NOT pass `model` — OpenCode selects its own free model automatically (no account/API key needed).\n2. **If the result has `running:true`** → the run is proceeding in the background and the worker keeps ITSELF alive; your calls are NOT its keep-alive. Do NOT treat `running:true` as a failure and do NOT fall back yet. Instead of re-polling in a tight loop, do useful work (transcribe digests, prepare fix-cycle context, update the ledger), then collect the terminal result in ONE bounded long wait: `opencode_status` with `{ runId, role, waitMs: 90000 }` — it blocks safely under the host's ~120s tool-call ceiling and returns the moment the run finishes (re-calling `opencode_delegate` with the SAME arguments also waits a bounded window). **To move on to the paid fallback, cancel EXPLICITLY**: `opencode_status` with `{ runId, role, cancel: true }` kills the worker before any FURTHER diff applies (a cancel refused with `applying:true` means a clean diff is landing right now — call status once more without cancel and take that result; after any cancel, check the role digest and `git status` before the paid fallback in case an earlier unit already landed). Never abandon by silence: an unwatched run keeps working and its clean diff still lands. **A real unit legitimately takes MINUTES** (measured: ~8 minutes for a 6-file feature unit on a free model), so `running:true` after one long wait is normal progress, not a hang.\n3. On `ok:true` (delegated) → the change is applied to the tree and a digest is written; proceed to review (`senior-reviewer` verifies the diff). Do NOT spawn the paid `{{ROLE}}`.\n4. On `ok:false` (skipped/failed/no-changes) → OpenCode declined or could not run. Re-spawn `{{ROLE}}` exactly as usual; this gate denies each role at most once per run, so the fallback spawn goes through.\n5. **If the host's safety reviewer rejects the `opencode_delegate` call** (e.g. Codex: \"rejected due to unacceptable risk\" because it would send code to an external service) AND the rejection says you may proceed if the user explicitly approves → do NOT silently fall back. Ask the user, in one line, for explicit approval, naming the risk: e.g. *\"Codex flagged OpenCode delegation because it sends this bounded task and the relevant code to OpenCode's hosted model. Approve sending it to OpenCode for this run? (Otherwise I'll use the paid worker.)\"* If the user explicitly approves, call `opencode_delegate` again with the SAME arguments — the reviewer names this as the sanctioned path, so it is NOT a workaround/circumvention; treat that approval as covering the rest of this run's delegations. If the user declines or does not answer, re-spawn `{{ROLE}}` as the paid fallback.\n6. **If the `opencode_delegate` tool is unavailable or its call could not complete** → re-spawn `{{ROLE}}` as the internal fallback; the one-denial guard prevents a loop. On Codex, an unavailable tool usually means the auto-registered MCP server has not been loaded yet — tell the user a ONE-TIME Codex restart enables it.\nTo stop routing this role through OpenCode, remove it from `openCode.delegateRoles` in local preferences.",
  "agent-model :: performance-main-agent": "Performance gate: local Traffic One preferences record performance.level=\"{{LEVEL}}\" (main-agent only), but you are spawning the `{{ROLE}}` subagent. If the user chose Balanced or High, first correct local preferences (`performance.level` plus matching `team.mode=\"subagents\"`) so the right model tier applies, then re-spawn with the runtime-resolved `model` when the host supports it. On Codex, also use the canonical underscore-form `task_name` and `fork_turns: \"none\"`. If the user really chose Low, do NOT spawn subagents — run the roles in this thread as the role roadmap checklist.",
  "agent-model :: performance-model-param": "ACTION: re-issue this spawn with `model: \"{{EXPECTED}}\"`. Nothing crashed — the host renders a declined spawn as an agent failure, but this is the Traffic One Performance gate (level={{LEVEL}}, host={{HOST}}) holding `{{ROLE}}` to the run's frozen model. {{PASSED_NOTE}}The model is set ONLY by this parameter — a model name in prompt text or a model-agnostic project agent contract has no effect. On Cursor, use the exact role→model value printed by model-gate; without the parameter the subagent inherits the parent model.{{ALTERNATES}} The runtime lineup comes from the active host snapshot in local Traffic One settings.\nFor Codex, also use the canonical underscore-form `task_name` and `fork_turns: \"none\"`; the child hook verifies the actual model exactly against the immutable run policy.",
  "agent-model :: spawn-claim-unavailable": "Traffic One spawn gate: the role claim for `{{ROLE}}` in run `{{RUN_ID}}` could not be recorded, so the spawn was blocked before a child started ({{REASON}}). Nothing is wrong with the run — its ledger still admits claims and the role is free — and this is not a model, team, or plan problem. Traffic One already retried once.\n\nA child spawned without a claim binds no role: it writes as the main agent, is invisible to the duplicate-spawn gate, and cannot be released when the run settles. Blocking the spawn is the recoverable outcome.\n\nRetry the SAME spawn, unchanged, in your next message. A concurrent hook holding the run's claims or ledger lock clears in about two seconds. If the same deny repeats more than twice, another process is wedged on this run's state: run `node ~/.traffic-one/bin/doctor.cjs --run \"{{RUN_ID}}\"` and fix what it reports before spawning again. Do NOT change the role, the model, or the task to work around it, and do NOT build the project inline instead.",
  "agent-model :: spawn-role-conflict": "Traffic One spawn identity gate: this spawn carries conflicting valid Traffic One role evidence in the same highest-priority tier: {{CANDIDATES}}. The spawn was blocked before a child started. Do not retry it unchanged and do not guess which role won. Correct or remove the stale identity field or marker so every valid item in that tier agrees on exactly one canonical role, then retry the same task. On Codex, keep one exact canonical task_name and ensure higher-tier agent_path/agent_type metadata, when present, names the same role.",
  "agent-model :: team-confirmation": "Team gate: spawning subagents needs `team.approved: true`, which the Traffic One setup wizard sets AUTOMATICALLY from the performance choice (performance.level=\"{{LEVEL}}\" ⇒ subagents). Local preferences currently have `team.approved !== true`, which means the wizard's performance/team step was not completed for this project — not that the user must approve a line-up in chat. Do NOT pop a chat \"approve the team?\" prompt and do NOT hand-edit preferences to set the flag. Re-open the Traffic One setup wizard and finish the performance/team step (it writes `team.approved: true` and shows the role→model line-up), then re-spawn with the per-role `model` on Claude, Cursor, or Codex. On Codex, also use the canonical underscore-form `task_name` and `fork_turns: \"none\"`. If the user wants Low/main-agent mode instead, they re-pick performance in the wizard; never bypass this gate for `team.mode=\"subagents\"`.",
  "agent-model :: verify-batch-running": "traffic-one — verification gate: `{{ROLE}}` must not start while the Step-0 OpenCode implementation batch for run `{{RUN_ID}}` is still pending — a review/test pass over pre-batch state wastes the whole round. Collect the terminal batch result in ONE bounded call: `opencode_status` with `{ runId: \"{{RUN_ID}}\", waitMs: 90000 }` (repeat while it returns running), or abandon the batch explicitly with `opencode_status {runId, cancel:true}` before falling back. Then re-issue this exact spawn — this gate denies at most once per run and role, so the retry always goes through.",
  "materialize :: digest-size": "[digest-size] Your `{{ROLE}}.md` digest is {{KB}} KB; the spec target is ≤2 KB (see `rules/common/agent-handoff-digests.md`). Re-write before completing your turn:\n  1. Use repo-relative paths, never absolute (drop `/Users/.../` prefixes).\n  2. Touched: file paths only, no parenthetical annotations.\n  3. Public contracts: delta-only — what changed vs the plan, not the full surface.\n  4. Open questions: at most 3 bullets; link to plan §, do not inline rationale.\nReviewer / tester / shipper read this digest INSTEAD of the diff; bloated digests defeat the token-economy layer.",
  "model-choice-gate :: model-choice-stop-first": "Traffic One model-choice gate: build paused until the user chooses how to handle unavailable Cursor model(s).\n\n{{TABLE}}\n\nPaste the table above to the user in chat and end your turn. Do not spawn subagents, scaffold directly, edit project files, install dependencies, or simulate the team inline until the user replies `fallback` or `enable`.",
  "model-choice-gate :: model-choice-stop-repeat": "Traffic One model-choice gate: build still paused. The user has not replied `fallback` or `enable` yet. Stop now and ask the user to choose; do not spawn subagents, scaffold directly, edit project files, install dependencies, or simulate the team inline.",
  "onboarding-gate :: browser-open-denied": "Traffic One does not open the setup link for the user — they open it themselves.\n\nPost the setup link in a CHAT MESSAGE instead, on its own line, as plain clickable text (not inside a code block), then run the wait command and keep your turn open.\n\nAn agent that opens the link tends to then believe it has \"already shared\" it and never posts it, which leaves the user with no link at all. Look at your own last visible chat message: if the link is not there, the user has not seen it.",
  "onboarding-gate :: claude-wait-background-denied": "This onboarding command was requested with run_in_background: true. A backgrounded run writes its output — including the setup link it prints — into a background task file the user never opens, and the turn ends with the user waiting on a link they were never shown.\n\n{{URL_LINE}}\n\nPost the setup link to the user in a CHAT MESSAGE — plain clickable text on its own line, not inside a code block — then re-run this SAME command in the FOREGROUND of this turn (run_in_background: false, timeout ~9 minutes / 540000 ms) and keep the turn open. Follow its printed instructions when it finishes.\n\n{{WAIT_CMD}}",
  "onboarding-gate :: claude-wait-link-first": "This notice is NOT visible to the user: Claude Code renders hook output and blocked commands inside a collapsed tool block, so the setup link has still never appeared in the conversation.\n\nCheck your own last VISIBLE chat message. Tool output, hook banners, and collapsed command blocks do not count — if the link is not in a message you wrote, the user has not seen it.\n\nPost this to the user in your NEXT CHAT MESSAGE, on its own line, as plain clickable text — not inside a code block. Do NOT open it yourself with a browser tool or an `open`/`xdg-open`/`start` command; the user clicks it:\n\nOpen Traffic One setup: {{URL}}\n\n{{LOCAL_FALLBACK}}\n\nOnly after that message is written, re-run the wait command in the FOREGROUND of the same turn (run_in_background: false, timeout ~9 minutes / 540000 ms) and keep the turn open:\n\n{{WAIT_CMD}}\n\nWhen it prints `TRAFFIC_ONE_SETUP_COMPLETE`, continue the original request.",
  "onboarding-gate :: codex-wait-link-first": "The setup link has not been posted to the user in this conversation yet, and this deny reason is the only channel that reaches you — so the user still has no link to click.\n\nPost this to the user in your NEXT MESSAGE, on its own line, as plain clickable text — not inside a code block. Do NOT open it yourself; the user clicks it and completes setup in their browser:\n\nOpen Traffic One setup: {{URL}}\n\n{{LOCAL_FALLBACK}}\n\nOnly after that message is written, re-run the wait command in the foreground of the same turn and keep the turn open:\n\n{{WAIT_CMD}}\n\nWhen it prints TRAFFIC_ONE_SETUP_COMPLETE, continue the original request.",
  "onboarding-gate :: cursor-wait-link-first": "This notice is NOT visible to the user: Cursor renders a blocked command inside a collapsed \"ran N commands\" block, so the setup link has still never appeared in the conversation.\n\nCheck your own last VISIBLE chat message. Tool output and collapsed command blocks do not count — if the link is not in a message you wrote, the user has not seen it.\n\nPost this to the user in your NEXT CHAT MESSAGE, on its own line, as plain clickable text — not inside a code block. Do NOT open it yourself with a browser tool or an `open`/`xdg-open`/`start` command; the user clicks it:\n\nOpen Traffic One setup: {{URL}}\n\n{{LOCAL_FALLBACK}}\n\nOnly after that message is written, re-run the wait command in the FOREGROUND of the same turn and keep the turn open:\n\n{{WAIT_CMD}}\n\nWhen it prints `TRAFFIC_ONE_SETUP_COMPLETE`, continue the original request.",
  "onboarding-gate :: kilo-opencode-architect-incomplete": "[traffic-one] {{HOST}} build — `.traffic-one/plan.md` exists but the architect phase is INCOMPLETE. You are the PARENT/orchestrator.\n\nDO NOT spawn any implementation role from the runtime capability contract yet. DO NOT patch `assignments.json` or `digests/{{RUN_ID}}/architect.md` yourself unless the user explicitly opts out of subagents.\n\nMissing architect deliverables: {{MISSING}}\n\nRespawn `senior-architect` via `{{TASK_TOOL}}` with:\n- `subagent_type: \"{{SUBAGENT_TYPE}}\"` — {{SPAWN_RULE}}\n- prompt line 1: `[t1-role: senior-<role>]` (substitute the spawned role; architect here)\n- {{ROLE_CONTRACT_INSTRUCTION}}\n- `Run ID: {{RUN_ID}}`\n- instruct the architect to finish project memory and semantic\n  `.traffic-one/runs/{{RUN_ID}}/architecture-input-v1.json`, then write\n  `.traffic-one/digests/{{RUN_ID}}/architect.md` with `PLAN_READY`; runtime\n  compiles architecture/verification, assignments, and work-unit bootstraps\n\nRuntime capability contract: {{PROFILE_SUMMARY}}.\n{{IMPLEMENTER_DIRECTIVE}}\n{{QA_DIRECTIVE}}\n\nImplementer spawns are blocked until the digest carries `PLAN_READY` on disk.",
  "onboarding-gate :: kilo-opencode-spawn-first": "[traffic-one] {{HOST}} build start — `team.mode=\"subagents\"` is ACTIVE and `.traffic-one/plan.md` is still missing. You are the PARENT/orchestrator.\n\nDO NOT write feature source, scaffold app files, or run package installs yourself in this thread.\nYour FIRST action: spawn `senior-architect` via the host `{{TASK_TOOL}}` tool:\n- `subagent_type: \"{{SUBAGENT_TYPE}}\"` — {{SPAWN_RULE}}\n- prompt line 1 MUST be: `[t1-role: senior-<role>]` (substitute the spawned role; architect here)\n- {{ROLE_CONTRACT_INSTRUCTION}}\n- include `Run ID: {{RUN_ID}}` and the user's original request\n- omit `model` on {{HOST}} unless the host documents a subagent model parameter\n\nRuntime capability contract: {{PROFILE_SUMMARY}}.\nDo not replace these detected surfaces, roots, framework conventions, skill buckets, or QA adapters with an unrelated default.\n\n{{IMPLEMENTER_DIRECTIVE}}\n{{QA_DIRECTIVE}}\nRead `.traffic-one/rules/common/senior-engineer-team.md` before the first eligible implementer spawn.",
  "onboarding-gate :: maintenance-triage-main-agent": "[MAINTENANCE PHASE — post-build triage] The main build is complete; this is an iteration request. This project runs in main-agent mode (no subagents). Pick the tier and scale your effort to it — you judge the TIER (the keyword hint is a prior, not a verdict). Route it yourself in one sentence and proceed; do not ask the user which tier or approach to use.\n- trivial — a CSS/styling tweak, copy/text, one i18n string, a rename, a single-file config change: make the edit directly, no planning ceremony.{{OPENCODE_CLAUSE}} Verify visually if the change is visual.\n- small — one component, one page/route, one small endpoint, or a scoped bug fix: implement it directly after a brief plan.\n- complex — a feature spanning layers, a data-model/schema change, auth, a migration, or an external integration: read and follow the `senior-eng-orchestrator` skill NOW and run its phases INLINE via the roadmap checklist — plan the feature, decide the surface, implement, then self-review and test. Do not spawn subagents.\nKeyword hint: {{HINT}} (confidence {{CONFIDENCE}}){{SIGNALS}}. If the user explicitly asked for a quick/small change, honor that. Full rubric: read the `task-triage` skill.",
  "onboarding-gate :: maintenance-triage-subagents": "[MAINTENANCE PHASE — post-build triage] The main build is complete; this is an iteration request. Pick the tier, then ROUTE it — in this (subagents) mode do NOT implement trivial or small work yourself in this thread; handing it to a cheaper worker is the whole point of post-build triage. You judge the TIER (the keyword hint is a prior, not a verdict); the routing for the chosen tier is required, not optional. State your routing in one sentence and proceed — do not ask the user which tier, worker, or model to use.\n- trivial — a CSS/styling tweak, copy/text, one i18n string, a rename, a single-file config change: spawn a `quick-fix` subagent with model \"{{CHEAPEST_MODEL}}\" on hosts whose spawn tool supports `model`; omit `model` on OpenCode/Kilo/Copilot/Windsurf unless the exact host tool documents support. On Codex use one fresh `spawn_agent` call with `task_name: \"quick_fix\"`, `fork_turns: \"none\"`, and `model: \"{{CHEAPEST_MODEL}}\"`; never retry with a generic task name, inherited/full history, or a different available model. Do NOT make the edit yourself.{{QUICK_FIX_OPENCODE_CLAUSE}} Give it the exact file(s), the precise change, and one verification step; the worker makes the change and verifies it (screenshot if visual). Include ONE line in the spawn prompt of the form `[t1-bounded-scope: {\"outputs\":[\"src/exact/File.tsx\"]}]` naming every exact repo-relative file the fix may create or modify (no globs or directories) — the runtime publishes the bounded WorkUnitContract from that line, and a spawn without it is denied.\n- small — one component, one page/route, one small endpoint, or a scoped bug fix: spawn the owning implementation role(s) directly at their normal tier. Use `senior-frontend` for UI/routes and `senior-backend` for server/data; when the bounded request genuinely touches both, spawn those two roles in parallel. On Kilo, each direct role uses built-in `general` with its first-line role marker and matching `.kilo/agents/senior-<role>.md` contract, with no `model`.{{SMALL_OPENCODE_CLAUSE}} Do NOT spawn `senior-architect` or create a feature plan unless the work turns cross-cutting.\n- complex — a feature spanning layers, a data-model/schema change, auth, a migration, or an external integration: read and follow the `senior-eng-orchestrator` skill NOW, before any edit, as a SINGLE-FEATURE run — the architect plans just this feature, decides frontend/backend/both and the per-role model tiers, then implement → review → test.\nKeyword hint: {{HINT}} (confidence {{CONFIDENCE}}){{SIGNALS}}. If the user explicitly asked for a quick/small change, honor that. Full rubric: read the `task-triage` skill.",
  "onboarding-gate :: materialization-not-converged": "traffic-one — this tool use was denied because Traffic One could not finish bringing this project's materialized rules and skills up to date, and a file-changing tool must not run against a half-converged project: `.traffic-one/rules` and `.traffic-one/skills` are the project's only copy of content a broken plugin root cannot resupply.\n{{DIAGNOSIS}}\nRe-issuing this tool call draws this same refusal. The cause above is a fact about the installation or about `.traffic-one/.one.json`, not about the tool you tried, so nothing about running it again changes it. Repair that cause if it is yours to repair; if it is not, report it to the user in the terms above and carry on with work that changes no files, which is not affected.",
  "onboarding-gate :: repaired-materialization": "Traffic One state was repaired/materialized before this tool use.\nThe attempted mutating tool has been denied once so it cannot run against stale `.traffic-one/.one.json`, rules, skills, or root agent context.\nrerun the same tool now; the canonical `.traffic-one/.one.json` and project-local materialization are current.",
  "onboarding-gate :: server-bootstrap-required": "Traffic One setup could not start inside this host's restricted hook sandbox ({{ERROR_CODE}}). Private preferences MUST remain in `~/.traffic-one/projects`; do not create `preferences.json`, `machine.json`, or onboarding runtime files inside the project.\n\nDo not search for a wizard tool, claim the preview is already open, or end the turn. Your NEXT action is to run this exact bootstrap command with the required approval:\n\n{{BOOTSTRAP_CMD}}\n\n{{HOST_PERMISSION_STEP}}\n\nThe bootstrap prints `TRAFFIC_ONE_SETUP_READY` and a live `Setup link:`, then exits. Post that URL to the user as a standalone clickable link in a chat message — do not open it yourself with a browser tool. Immediately afterward run this normal waiter and keep the turn active:\n\n{{WAIT_CMD}}\n\nWhen it prints `TRAFFIC_ONE_SETUP_COMPLETE`, immediately continue the original request. If it prints `TRAFFIC_ONE_SETUP_PENDING`, run the exact same waiter again. If it prints `TRAFFIC_ONE_TECH_CLASSIFY_REQUIRED`, follow its printed classification instructions (inspect the repo, run the printed `--set-tech` command), then re-run. Building, installs, and subagent work remain blocked until completion.",
  "onboarding-gate :: server-bootstrap-required-compact": "Traffic One setup needs approved access to its user-local state at `~/.traffic-one/projects` ({{ERROR_CODE}}).\n\nRun with approval: {{BOOTSTRAP_CMD}}\n\nIt prints the live setup link and exits. Show that link, then keep setup active with:\n{{WAIT_CMD}}\n\nBuilding remains blocked until the waiter reports completion.",
  "onboarding-gate :: server-deny-reason": "Traffic One setup is required before building in this project. Setup now happens on the\nTraffic One dashboard in the user's web browser — they sign in or create an account,\nthen finish a few setup steps. Your job is to SURFACE THE LINK to the user and then\nwait. Do NOT try to answer the setup questions yourself, and do NOT create or edit\n.claude/launch.json.\n\nPost this clickable setup link to the user as your FIRST visible action, before any\nwait command — put it in a CHAT MESSAGE on its own line, not buried in a terminal\nblock. Tool output and collapsed command blocks do NOT count as showing it: several\nhosts hide them, so if the link is not in a message you wrote, the user has not seen\nit. Show it as plain clickable text only; do NOT open it with a browser/navigate tool\nor an `open`/`xdg-open`/`start` command — the user clicks it themselves:\n\n    Open Traffic One setup: {{URL}}\n\n{{LOCAL_FALLBACK}}\n\nAll setup logic and saves stay on this machine; the dashboard is just the UI.\n\nCONTINUE AUTOMATICALLY — do NOT end your turn after showing the link. Immediately run\nthis command in the FOREGROUND of this turn (never as a background task) and keep your\nturn open; it BLOCKS until the user finishes setup (run it with a long timeout,\n~9 minutes / 540000 ms):\n\n{{WAIT_CMD}}\n\nWhen it prints `TRAFFIC_ONE_SETUP_COMPLETE`, IMMEDIATELY continue the user's original\nrequest and build it end to end — do not stop to ask \"what next?\". If it prints\n`TRAFFIC_ONE_SETUP_PENDING` (it timed out before setup finished), run the exact same\ncommand again; after a couple of pending rounds with no progress, tell the user to\nfinish setup and wait for their go-ahead. (If you genuinely cannot run a shell command,\nfall back to: when the user says setup is done, continue the request.)\n\nRead-only orientation (pwd, ls, reading files, searching) and the wait command above\nare allowed now, but feature writes, installs, and subagent work stay blocked until\nsetup completes. Do NOT restart the host and do NOT answer these setup questions\nyourself in chat — setup happens in the browser.\n\nDon't use Traffic One: if the user says they don't want Traffic One for this\nproject, run this command instead — it saves their choice outside the project (no\nfiles are added to it) and Traffic One stays silent here until they ask for it again:\n\n{{DECLINE_CMD}}",
  "onboarding-gate :: server-deny-reason-links-shown": "Traffic One setup is required before building — and the user HAS the setup wizard\nopen in their browser right now (the setup server saw it load). Do NOT print the link\nagain: they are mid-setup, and a repeated link reads as \"start over\". Only repeat it\nif the user says they cannot find it.\n\nCONTINUE AUTOMATICALLY — run this wait command NOW, in the FOREGROUND of this turn\n(never as a background task, and do not open any URL with a browser tool), with a long\ntimeout (~9 minutes / 540000 ms). It BLOCKS until the user finishes setup and returns\nIMMEDIATELY if setup is already complete:\n\n{{WAIT_CMD}}\n\nWhen it prints `TRAFFIC_ONE_SETUP_COMPLETE`, IMMEDIATELY continue the user's original\nrequest. If it prints `TRAFFIC_ONE_SETUP_PENDING` (it timed out before setup\nfinished), run the exact same command again. Read-only orientation stays allowed;\nfeature writes, installs, and subagent work stay blocked until setup completes.\n\nDon't use Traffic One: if the user says they don't want it for this project, run:\n{{DECLINE_CMD}}",
  "onboarding-gate :: server-deny-reason-repeat": "Traffic One setup is still pending — building stays blocked until setup finishes.\nPost this setup link to the user in a chat message — the user opens it, not you: {{URL}}\n{{LOCAL_FALLBACK}}\nKeep your turn open by running the wait command again (long timeout, ~9 minutes):\n\n{{WAIT_CMD}}\n\nWhen it prints `TRAFFIC_ONE_SETUP_COMPLETE`, IMMEDIATELY continue the user's original\nrequest. Full instructions were given on the first denial this session.\nDon't use Traffic One: if the user says they don't want it for this project, run:\n{{DECLINE_CMD}}",
  "onboarding-gate :: setup-pending": "Traffic One needs a quick setup before it can build in this project. When you start\na coding task, Traffic One gives you a link to the Traffic One dashboard — the user\nopens it in their browser, signs in, and finishes a few setup steps there (all logic\nand saves stay on this machine). Share that link with the user when it appears.\n\nUntil then only read-only orientation is in effect: do not scaffold, install, or\nwrite feature code, do not invoke build/design skills, and do NOT try to ask these\nsetup questions yourself in chat — setup happens in the browser. Do not tell the user\nto restart the host. The durable per-project `pluginUse` question is asked before\nthe wizard opens; if the user declines there, Traffic One remains silent for this\nproject until they explicitly ask to enable it again.",
  "onboarding-gate :: stop-setup-link-posted": "You are ending your turn while Traffic One setup is still pending. The setup link is already posted in the conversation — do NOT post it again; a repeated link reads as noise.\n\nRun this wait command NOW in the FOREGROUND (run_in_background: false, timeout ~9 minutes / 540000 ms) and keep the turn open. It returns immediately if setup is already complete; when it prints TRAFFIC_ONE_SETUP_COMPLETE, continue the original request:\n\n{{WAIT_CMD}}",
  "onboarding-gate :: stop-setup-links-shown": "You are ending your turn while Traffic One setup is still in progress — the user has the setup wizard open in their browser right now (the setup server saw it load). Do NOT repost the link: a repeated link reads as \"start over\".\n\nRun this wait command NOW in the FOREGROUND (run_in_background: false, timeout ~9 minutes / 540000 ms) and keep the turn open. It returns immediately if setup is already complete; when it prints TRAFFIC_ONE_SETUP_COMPLETE, continue the original request:\n\n{{WAIT_CMD}}",
  "onboarding-gate :: stop-setup-required": "You are ending your turn while Traffic One setup is still required, and the setup link has not been confirmed delivered — if the link is not in a message you wrote, the user has no way to continue setup.\n\nPost this setup link to the user NOW, in a chat message, on its own line, as plain clickable text — not inside a code block. Do NOT open it yourself; the user clicks it:\n\nOpen Traffic One setup: {{URL}}\n\n{{LOCAL_FALLBACK}}\n\nThen run this wait command in the FOREGROUND (run_in_background: false, timeout ~9 minutes / 540000 ms) and keep the turn open. When it prints TRAFFIC_ONE_SETUP_COMPLETE, continue the original request:\n\n{{WAIT_CMD}}",
  "onboarding-gate :: team-mode-downgrade-guard": "Traffic One team mode guard: local Traffic One preferences currently record `team.mode=\"subagents\"`. This write would switch the project to `team.mode=\"main-agent\"`, but the latest user prompt did not explicitly say they no longer want subagents and want Low/main-agent mode. Ask the user to say that explicitly before rewriting local `performance.level=\"low\"` and `team.mode=\"main-agent\"`. Do not use `team.source=\"unavailable\"` or a state rewrite as a workaround.",
  "onboarding-gate :: team-mode-marker-guard": "Traffic One team mode guard: `team.modeChangeApproval` is an internal, single-use marker that can only be written by the UserPromptSubmit hook after an explicit user request. Do not add or refresh it in `.traffic-one/.one.json` manually.",
  "onboarding-gate :: team-mode-switch-authorized": "The latest user prompt explicitly requested switching away from subagents to Low/main-agent mode. The next local Traffic One preference write may change `performance.level` to \"low\" and `team.mode` to \"main-agent\"; this authorization is single-use and expires in 10 minutes.",
  "onboarding-gate :: tech-classify-required": "traffic-one — this existing codebase could not be identified deterministically: none of the known stack markers matched, so YOU must classify it before setup can continue.\n\n1. Inspect the repo yourself — package manifests, lockfiles, entrypoints, framework configs. A few READS are enough; do not modify anything.\n2. Submit the tech by running this command with the surfaces you identified appended:\n{{SET_TECH_TEMPLATE}}\n   Append: `--frontend=<id>` and `--backend=<id>` (both REQUIRED — use `none` when that surface does not exist), plus optional `--mobile=<id>`, `--realtime=light` (when a websocket/realtime layer exists), and `--evidence='<short proof>'` (e.g. --evidence='express + mongoose in package.json').\n   frontend ids: none, react-vite, nextjs, nuxt, vue, svelte, angular, astro, solid, remix, other\n   backend ids: none, supabase, external-api, node, nestjs, python, django, fastapi, go, rust, java, kotlin, php, laravel, dotnet, firebase, mongo, other\n   mobile ids: ionic-capacitor, react-native-expo, swift-native, kotlin-android, flutter, none\n   Use `other`/`none` when nothing fits — NEVER invent an id; the command is denied unless every id is from these lists.\n\nPartial signals already detected:\n{{HINTS}}\n\nOn success it prints TRAFFIC_ONE_TECH_RECORDED and then the setup wizard's `Setup link:` — post that link to the user in chat and run the printed waiter command, exactly as in the normal setup flow. Run the command EXACTLY as printed plus your surface flags — no pipes, redirection, or `&&`; the gate allow-lists the precise argv.",
  "onboarding-gate :: windsurf-server-deny-reason": "Traffic One setup is required before building.\n\nBefore running any tool, show the user this standalone clickable setup link — do not open it yourself:\n[Open Traffic One setup]({{URL}})\n\n{{LOCAL_FALLBACK}}\n\nKeep the current turn active by running this wait command (timeout ~9 minutes):\n{{WAIT_CMD}}\n\nWhen it prints `TRAFFIC_ONE_SETUP_COMPLETE`, immediately continue the original request.",
  "onboarding-gate :: windsurf-server-deny-reason-repeat": "Traffic One setup is still pending.\n\nBefore running any tool, show the user this standalone clickable setup link — do not open it yourself:\n[Open Traffic One setup]({{URL}})\n\n{{LOCAL_FALLBACK}}\n\nKeep the current turn active by running this wait command:\n{{WAIT_CMD}}\n\nWhen it prints `TRAFFIC_ONE_SETUP_COMPLETE`, continue the original request.",
  "plan-guard :: architect-memory-baseline-gate": "Architect completion gate: do not write `PLAN_READY` until the required `.traffic-one` project-memory baseline exists with real content. Missing or incomplete: {{MISSING}}. Write the missing memory files yourself (do not delegate `.traffic-one/*` to OpenCode), then update `.traffic-one/digests/<runId>/architect.md` and only then emit `PLAN_READY`.",
  "plan-guard :: architect-opencode-queue-gate": "Architect completion gate: OpenCode is enabled but the plan is missing at least 3 runnable machine-readable delegation units. Include `<!-- opencode-delegate:start -->` … `<!-- opencode-delegate:end -->` with 3–6 bounded units (`- id: <stable-unit-id> | role: … | files: … | task: …`) in `.traffic-one/plan.md` before emitting `PLAN_READY`. The orchestrator runs `opencode_delegate_from_plan` from that block BEFORE spawning implementers.",
  "plan-guard :: architect-opencode-queue-policy-gate": "Architect completion gate: OpenCode queue files or metadata do not match this run's compiled contract: {{ERRORS}}. This is a recoverable architect rewrite, not a crashed run. Fix the queue block in `.traffic-one/plan.md` (stable unique ids, parseable `files:`, explicit `depends:` edges for overlaps) and re-emit `PLAN_READY`. Scope errors above list the owning role's real compiled in-scope files — retarget each unit's `files:` to those exact paths, or declare the module in ArchitectureInputV1 so runtime compiles the output you need.",
  "plan-guard :: architect-opencode-self-delegation-gate": "Architect completion gate: this run is already hosted by OpenCode/Kilo, so `.traffic-one/plan.md` must not include an OpenCode delegation queue or `opencode-delegate` marker. Remove the self-delegation block before emitting `PLAN_READY`; implementer work runs directly on the current host.",
  "plan-guard :: architect-planning-allowlist-gate": "Architect scope gate: `senior-architect` may write only the semantic plan/project-memory files, NEW ADRs under `.traffic-one/decisions/<name>.md` (existing ones are append-only across runs — use the `<runId>-` prefix to rewrite your own), `.traffic-one/runs/<runId>/architecture-input-v1.json`, and its architect digest. `{{TARGET}}` is runtime- or implementer-owned. Do not scaffold packages, workspace/config/source files, barrels, Tailwind assets, tests, or assignments; emit semantic ArchitectureInputV1 and let runtime compile the work units.",
  "plan-guard :: architecture-assignment-gate": "Architecture assignment gate: the runtime-compiled outputs are not covered before spawn. {{ERRORS}}. Amend semantic ArchitectureInputV1 and re-run PLAN_READY compilation; never edit or widen runtime-owned assignments.",
  "plan-guard :: architecture-contract-gate": "Architecture contract gate: do not emit `PLAN_READY` until the run's `architecture-input-v1.json` is valid and runtime compilation succeeds. {{ERROR}}. The architect may change only semantic routes/modules/component placement/uiPrimitives/i18n/exceptions; runtime owns roots, roles, outputs, baseline, and hashes.",
  "plan-guard :: architecture-input-gate": "Architecture input gate: ArchitectureInputV1 may contain only semantic routes, modules (including component placement), exact UI primitive identifiers, i18n locale/exact-brand intent, and narrow exception requests. Runtime owns profiles, roots, roles, limits, output paths, and the baseline. Fix: {{ERRORS}}.",
  "plan-guard :: architecture-input-owner-gate": "Architecture input gate: only the parent-bound `senior-architect` planning role may write ArchitectureInputV1; active role is `{{ROLE}}`. Retrying the write, or making it through shell instead, draws the same refusal — the owner is decided by the run's role claim, not by the tool. Record the semantic change you wanted (routes, modules including component placement, exact UI primitive identifiers, i18n locale/exact-brand intent, or a narrow exception request) in your own digest instead, and let the orchestrator route it to `senior-architect`, who owns this artifact and re-runs PLAN_READY compilation from it.",
  "plan-guard :: architecture-input-shell-unverified": "Architecture input gate: this shell command references `{{TARGET}}` but its write payload cannot be reconstructed for validation, and the current on-disk file is not valid ArchitectureInputV1 ({{ERRORS}}). Read-only checks pass once the on-disk file is valid; to (re)write it, use the role-scoped Write/Edit tools with the complete semantic JSON instead of shell eval.",
  "plan-guard :: asset-extension-mismatch": "Asset gate: this write puts SVG/XML text into a bitmap image path such as `.png`, `.jpg`, `.webp`, or `.avif`. The bytes are markup rather than an encoded bitmap, so every consumer that decodes by extension — an image tag, an image pipeline, a favicon reader — reads a corrupt file, and no build or typecheck step in this run will report it. Re-issuing the same content draws the same refusal — the rule compares the extension against the leading bytes of the content, so reformatting or minifying the markup does not satisfy it. Save this content at a `.svg` path and update the references to it, or supply a real encoded bitmap for the bitmap path; this is a file-integrity check, so it holds on an existing codebase too.",
  "plan-guard :: bootstrap-publication-gate": "Bootstrap gate: the parent could not atomically refresh the role/rule/skill and work-unit envelopes against the compiled architecture and verification contracts. No implementer may spawn until the immutable envelopes are published.",
  "plan-guard :: capability-no-implementer-gate": "Capability gate: this project's saved stack selection resolves to a capability profile with NO implementation role — {{PROFILE}}. `PLAN_READY` is denied because neither `senior-frontend` nor `senior-backend` is eligible, so no implementer can be spawned and nothing planned here could ever be built. This is a STACK-SELECTION defect in the project's `.traffic-one/.one.json`, not a planning mistake: no change to `architecture-input-v1.json` can fix it, and re-emitting `PLAN_READY` will be denied identically. Tell the user their saved selection names no buildable surface, and ask them to re-run Traffic One setup (or correct `frontend`/`backend` in `.traffic-one/.one.json`) so the project has a real web/native UI, a real backend, or both. Runtime freezes the capability profile when a run id is minted, so the corrected selection takes effect only in a NEW run — run `{{RUN_ID}}` must be replaced, not retried.",
  "plan-guard :: component-placement": "Components must live in {{TARGET}} — not directly in src/.",
  "plan-guard :: contract-self-conflict": "Contract satisfiability gate: the compiled plan demands outputs its own write gates forbid — {{CONFLICTS}}. `PLAN_READY` is denied before any implementer spawns: a role facing this contract would be hard-denied on a mandatory output and the run would deadlock. Fix the semantic ArchitectureInputV1 (routes/modules/placement/i18n/exceptions) so every compiled output is writable, then re-emit `PLAN_READY`.",
  "plan-guard :: cross-feature-import": "Cross-feature import detected ({{CURRENT}} -> {{CROSS}}). Share via packages/ui, packages/ui-native, packages/utils, or a feature-agnostic store slice.",
  "plan-guard :: css-ts-import": "`.css.ts` (vanilla-extract) imports are no longer permitted — this file imports a generated vanilla-extract stylesheet module. Those modules mean something only under the vanilla-extract build plugin this stack does not run, so without it the import resolves to plain TypeScript whose class names were never emitted into a stylesheet and the component renders unstyled instead of failing loudly. Re-issuing the file unchanged draws the same refusal — the rule reads the import specifier, so renaming the stylesheet module while keeping the import does not satisfy it. Replace the imported style references with Tailwind utility classes in this same file and theme them through the HSL CSS variables in `globals.css`.",
  "plan-guard :: deep-relative-package": "Workspace import gate: this file reaches into another workspace package through a `../../../packages/…` relative path instead of importing that package by name. A deep relative path bypasses the package entry point, breaks the moment either side moves, and hides the dependency from the workspace resolver the build and the package graph read. Re-issuing the same import draws the same refusal — the rule reads the specifier, so adding or removing a `../` level does not satisfy it. Replace the specifier with the workspace package name (`@app/ui`, `@app/ui-native`, `@app/utils`) in this same file — the fix is an edit to the import line, never a relocation.",
  "plan-guard :: default-export": "Use named exports only for reusable components — this file declares a default export, and the compiled feature entry `features/<name>/index.tsx` is a module entry rather than a route file, so it is covered too. A default export carries no name across the import boundary, so each consumer may spell it differently and a later rename never propagates to any of them. Re-issuing the file unchanged draws the same refusal — the rule reads the default-export declaration itself, so moving it down the file or wrapping it changes nothing. Route files — Expo Router files under `app/` and web page components under `src/pages/` — are the stated exception; everywhere else the fix is a one-token rename inside this same file plus the matching change at each import site, never a relocation.",
  "plan-guard :: expo-route-service-files": "Expo Router placement gate: every file under `app/` is part of the route tree and must stay thin, and this write puts a `.service`/`.store`/`.hook`/`.query`/`.slice`/`.api` module there. Expo Router derives navigation from that directory, so a service module placed in it joins the route surface instead of staying a module the routes import. Re-issuing the same path draws the same refusal — the rule reads the `app/` path shape and not the project platform, so it fires on an `app/` directory in a web workspace too. Move the module to `src/features/<name>/`, `src/services/`, or a `packages/*` workspace and import it from the thin route file; if none of those is in your compiled allowlist, name this path in your digest with verdict `BLOCKED`.",
  "plan-guard :: finding-allowlist-gap": "Finding-satisfiability gate: {{PATHS}} is named as work to do, but it is outside EVERY role's runtime-owned WorkUnitContract for run `{{RUN_ID}}`. The role you would hand this to cannot write it — the run-team gate denies the write with STRUCT_ASSIGNMENT_ALLOWLIST_GAP, and a fix cycle cannot replan, so the loop never closes. Do one of three things instead: point the finding at a path a role already owns; drop it; or record it explicitly as DEFERRED (or REPLAN) on the same line, with the reason, so the next run's ArchitectureInputV1 compiles a home for it. Never hand a role an instruction its allowlist forbids.",
  "plan-guard :: frontend-collapse-gate": "Frontend completion gate: do not write `IMPLEMENTED` with collapsed source. `{{FILE}}` packs an entire component/route onto one line. Collapsed or minified product source is a defect even when build and typecheck pass. Format it and split routes, pages, features, and shared components according to the compiled architecture before re-emitting `IMPLEMENTED`.",
  "plan-guard :: frontend-emit-config-gate": "Frontend completion gate: {{PROBLEMS}}. The stock Vite template emits compiled `.js`/`.d.ts` next to every source on the first build, and the stale output can shadow the module at import time. Fix exactly this: set `\"noEmit\": true` in the app tsconfig, remove `\"composite\": true`, and use `\"build\": \"tsc --noEmit && vite build\"`, `\"typecheck\": \"tsc --noEmit\"`. Then re-emit `IMPLEMENTED`.",
  "plan-guard :: frontend-eslint-survival-gate": "Frontend completion gate: {{PROBLEMS}}. The scaffolded eslint config is the project's quality bar — the error-grade rules (`max-lines`, `no-restricted-imports`) replaced retired deterministic gates and CI runs them after this build ends. Extend the config freely, but restore the scaffolded error rules before re-emitting `IMPLEMENTED`.",
  "plan-guard :: frontend-structure-completion-gate": "Frontend completion gate: the runtime structure report failed ({{FINDINGS}}). Fix every blocking finding, then write `IMPLEMENTED` again — the gate re-scans the current tree on that write. Per-component LOC, function-count, and component-count findings remain warnings during this rollout; module size is owned by the compiled eslint `max-lines` rule — the project's own `lint` run refuses an oversized module, so split it. Integration findings block too: orphan modules, unused API packages, inert styling, a missing i18n runtime (`STRUCT_I18N_RUNTIME`), and catalog validation (`STRUCT_I18N_CATALOG` — keys non-empty in every declared locale). Hardcoded-copy findings (`STRUCT_HARDCODED_COPY`, `STRUCT_I18N_REACT_TRANS`) block only on profiles without a compiled AST lint layer; where the scaffolded eslint config carries the i18n rule, the project's own `lint` run owns them. React child copy uses `<Trans>` with namespace, key, and fallback.",
  "plan-guard :: frontend-structure-hot-gate": "Structural gate: {{FINDINGS}}. Entrypoints may only bootstrap the app; route pages must be separate compiled modules. Formatting the same monolith across more lines does not satisfy this gate.",
  "plan-guard :: frontend-structure-scan-incomplete": "Frontend completion gate: STRUCT_SCAN_INCOMPLETE after {{SCANNED}} product source files. This is recorded, not blocking: hitting the scan bound raises `uiImpact` to the truncated-scan floor on this run's verification contract, so the run owes more browser evidence rather than less. Narrow generated/output roots or split the project contract so the whole owned tree is judged.",
  "plan-guard :: implementer-collapse-gate": "Implementer completion gate: do not write `IMPLEMENTED` with collapsed source. `{{FILE}}` packs an entire function/component onto a single line — collapsed/minified source is a defect even when build, typecheck and lint pass, and the project formatter could not repair it. Write one statement per line, run the project formatter, and re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-contract-delivery-gate": "Implementer completion gate: `IMPLEMENTED` is forbidden while {{COUNT}} of role `{{ROLE}}`'s {{PLANNED}} compiled modules do not exist and were never observed as changed ({{MISSING}}). `changedPaths` unions the observed diff with every PLANNED output, so a contract can look complete while the files were never written — a verdict must describe what was delivered, not what was planned. Write the missing modules, or report `BLOCKED` naming them. Do not re-emit `IMPLEMENTED` until each one exists.",
  "plan-guard :: implementer-crawl-origin-gate": "Implementer crawl origin gate: `{{FILE}}` ships an unusable production origin — {{DETAIL}}. Crawl assets are published verbatim, so an invented origin is a live defect, not a placeholder. Generate these files from the public site-url env var (`VITE_SITE_URL` or the framework equivalent) and fail generation when it is unset; leave the deploy origin `Unverified` in project memory until the user supplies it. Then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-format-coverage-gate": "Implementer format coverage gate: the `{{MANIFEST}}` \"{{SCRIPT}}\" script runs `{{COMMAND}}`, whose arguments never reach compiled outputs including {{UNCOVERED}}. A formatter that skips owned source proves nothing — it passes while those files are unformatted. Check the whole project instead (`prettier --check .`) and put build output, lockfiles, and `.traffic-one` in `.prettierignore`, then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-format-parity-gate": "Implementer format parity gate: role `{{ROLE}}` owns formatter config `{{CONFIG}}`, but `prettier` is not declared in `{{MANIFEST}}` dependencies/devDependencies. A script or config that names an absent tool makes verification meaningless. Add `prettier` with the selected package manager at tooling root `{{TOOLING_ROOT}}`, then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-format-toolchain-gate": "Implementer format toolchain gate: role `{{ROLE}}` owns compiled formatter outputs at `{{TOOLING_ROOT}}`, but no Prettier config, `format`/`format:check` scripts, or `prettier` dependency is present. Create `{{CONFIG}}`, add matching scripts and the dependency to `{{MANIFEST}}`, run the formatter, then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-lint-invocation-gate": "Implementer lint gate: the root `package.json` \"lint\" script runs `{{SCRIPT}}`, which never invokes the per-package `lint` in {{MANIFESTS}}. A linter that is installed, scripted, and never run is not coverage — the compiled AST quality rules silently stop applying to those packages. Broadcast to every workspace member (`pnpm -r lint`, `turbo run lint` with no filter) or name each package in the filter, run it clean, then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-lint-toolchain-gate": "Implementer lint gate: role `{{ROLE}}` owns the compiled `{{CONFIG}}`, whose AST rules are this run's quality verdict for UI source, but {{MISSING}} is absent from `{{MANIFEST}}`. The write-time lexical copy scanners are warnings on this profile on exactly the promise that the project's own `lint` runs — a lint layer that cannot run is an enforcement gap, not a style nit. Add the missing entries (the scaffold seeds `eslint` plus the plugins the config imports), run `lint` clean, then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-test-toolchain-gate": "Implementer test toolchain gate: role `{{ROLE}}` owns `{{MANIFEST}}`, and the contract compiles tester-owned runner configs there, but {{MISSING}} is absent. The tester owns the configs and never the manifest, so it cannot install its own runner — it inherits a config for a tool that is not there and has no way to run the suite. When the verification contract requires performance evidence, project-local `lighthouse` belongs in the same manifest for the same reason. Add the missing dependencies and scripts to `{{MANIFEST}}`, then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-typecheck-invocation-gate": "Implementer typecheck gate: the root `package.json` \"typecheck\" script runs `{{SCRIPT}}`, which never invokes the per-package `typecheck` this contract demanded in {{MANIFESTS}}. A compiler that is installed, scripted, and never run is not coverage — the project's own command reports success while the errors stay unreported. Broadcast to every workspace member (`pnpm -r typecheck`, `turbo run typecheck` with no filter) or name each package in the filter, run it clean, then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-typecheck-toolchain-gate": "Implementer typecheck gate: role `{{ROLE}}` owns compiled TypeScript outputs, but no `typescript` dependency or `typecheck` script exists in {{MANIFESTS}}. `IMPLEMENTED` without a runnable compiler is unverifiable — the type errors surface later in a sibling role's build instead. Add `typescript` and a `typecheck` script (`tsc --noEmit`) to the tooling root, run it clean, then re-emit `IMPLEMENTED`.",
  "plan-guard :: implementer-verification-skipped-gate": "Implementer verification gate: this digest reports a required command as skipped or unavailable — \"{{EVIDENCE}}\" — directly alongside `IMPLEMENTED`. A verdict is a claim that the owned scope was verified, so an unrun build/typecheck/lint makes it unverifiable and the errors surface later in a sibling role's build. Install the toolchain at its owning manifest, run the command to completion, record the real outcome, then re-emit `IMPLEMENTED`. If the command genuinely does not apply, say why without claiming it was skipped.",
  "plan-guard :: lighthouse-claim-reconciliation-gate": "Page-speed claim gate: this digest reports Lighthouse performance {{CLAIMED}} — \"{{EVIDENCE}}\" — but the canonical QA runner measured {{MEASURED}} for run `{{RUN_ID}}`. A self-run audit is not the run's evidence: it can use a different Lighthouse version, a dev server, or a build from another run, and its report files are not run-scoped. Quote the runner's number (`.traffic-one/reports/qa/{{RUN_ID}}/lighthouse-evidence-v1.json`), or re-run the canonical sweep and quote the fresh one.",
  "plan-guard :: materialization-gate": "Materialization gate: stack context for {{FINGERPRINT}} has not been materialized on disk yet. Run `node -e \"const p=require('node:path'),e=process.env,r=p.resolve(e.TRAFFIC_ONE_PLUGIN_ROOT||e.CURSOR_PLUGIN_ROOT||e.CODEX_PLUGIN_ROOT||e.CLAUDE_PLUGIN_ROOT||process.cwd());process.argv.splice(1,0,'traffic-one-runtime');require(p.join(r,'scripts','hook-runtime.cjs'))\" materialize-project` from the project root and verify `.traffic-one/rules/**`, `.traffic-one/skills/**`, `.traffic-one/manifest.json`, root `AGENTS.md`, and root `CLAUDE.md` exist before writing feature source.",
  "plan-guard :: monorepo-package-json": "New-project monorepo gate: stack=default / React-Vite new projects must start with the Traffic One Turborepo root package.json: `private: true`, `packageManager: pnpm@...`, and a workspace declaration (`pnpm-workspace.yaml` or package.json `workspaces`) for `apps/*` and `packages/*`. Read `rules/modes/new-project.md` and scaffold the monorepo before feature code.",
  "plan-guard :: monorepo-root-flat-scaffold": "New-project monorepo gate: root-level TypeScript app config files (`tsconfig.json`, `tsconfig.app.json`, `tsconfig.node.json`, etc.) are not allowed for this stack. Complete the architect phase and scaffold the Turborepo workspace (`pnpm-workspace.yaml`, `apps/web/`, `packages/*`, `tsconfig.base.json`) instead of creating a flat root Vite layout.",
  "plan-guard :: monorepo-root-vite": "New-project monorepo gate: root Vite app files are not allowed for this stack. Use `apps/web/` for the React app and create the required `packages/*` workspaces first; see `rules/modes/new-project.md`.",
  "plan-guard :: native-dom-tags": "React Native has no DOM — this `.tsx` uses one of the `div`, `span`, `button`, `a`, or `input` tags, which the React Native renderer has no component for. The bundle still builds and typechecks, so this fails on the device at runtime rather than in any verification command this run will execute, which is why it is refused at write time. Re-issuing the file unchanged draws the same refusal — the rule matches the tag names in the source, so re-exporting them from a shim module does not satisfy it. Replace each one with its native primitive in this same file: `View` for `div`, `Text` for `span`, `Pressable` for `button` and `a`, and `TextInput` for `input`.",
  "plan-guard :: native-inline-style": "No inline object styles on React Native — this `.tsx` passes an inline style object, and NativeWind `className` is where a static style belongs on this stack. A style object literal is allocated again on every render and sits outside the class system the rest of the UI is themed through, so the same constant is restated per component instead of resolving to one utility. Re-issuing the file unchanged draws the same refusal — unlike the web rule, this one denies derived values too, so making a value computed does not satisfy it. Express the constant styles as a `className` string on the same element and keep `StyleSheet.create` for values that genuinely animate or are measured at runtime; both edits stay inside this same file.",
  "plan-guard :: no-any": "Avoid `any` — this non-test `.ts`/`.tsx` annotates a value with the `any` type, which turns off type checking for every downstream use of that value. An `any` spreads silently through assignments and return types, so the errors it hides surface later in a sibling role build instead of in your own, where they cost a fix cycle just to attribute. Re-issuing the file unchanged draws the same refusal — the rule reads the annotation, so widening it to an array of `any` or casting through it does not satisfy it. Replace the annotation with `unknown` plus a narrowing check, a precise interface, or a discriminated union in this same file; files in test scope are exempt, so a mock or fixture may keep its coarse typing.",
  "plan-guard :: opencode-external-temp-shell": "OpenCode/Kilo external-path gate: do not write scratch logs or build output under `/tmp`, `/private/tmp`, or `/var/tmp` from a model command. Those paths trigger host external-directory permission prompts and can stall the run. Write temporary diagnostics inside the project, for example `.traffic-one/tmp/<runId>/`, or print the output to stdout.",
  "plan-guard :: opencode-reserved-files": "traffic-one — OpenCode reservation: `{{TARGET}}` is reserved by the RUNNING delegated unit `{{UNIT_ID}}` ({{UNIT_ROLE}}) in run `{{RUN_ID}}` — a paid write here would collide with the diff that unit is about to apply. Reserved for it: {{FILES}}. Work on your NON-reserved files now and come back to this path last; if it stays reserved when everything else is done, record the path and unit id under Open questions in your digest — the ORCHESTRATOR (not you) waits for or cancels the delegation. Bounded: the reservation clears the moment unit `{{UNIT_ID}}` ends (or its executor dies).",
  "plan-guard :: pages-service-files": "Route-page placement gate: `src/pages/` holds route components, and this write puts a `.service`/`.store`/`.hook`/`.query`/`.slice`/`.api` module inside it. Data access and state parked next to one route is the shape that later forces a second route to import across the pages tree, which is the coupling this layout exists to prevent. Re-issuing the same path draws the same refusal — the rule reads the path, so renaming the export or shrinking the file changes nothing. Write the module at `src/services/`, `src/features/<name>/`, or a `packages/*` workspace instead and import it from the page; if none of those is in your compiled allowlist, name this path in your digest with verdict `BLOCKED` so the architect can compile a home for it.",
  "plan-guard :: plan-architect-self-gate": "Plan gate: .traffic-one/plan.md is missing on this new project. You ARE the `senior-architect` for this run — write `.traffic-one/plan.md`, project memory, and semantic ArchitectureInputV1; do not spawn another architect and do not scaffold implementation files.",
  "plan-guard :: plan-gate": "Plan gate: .traffic-one/plan.md is missing on a new project. Run the `senior-architect` subagent (or the `senior-eng-orchestrator` skill) to produce the plan before writing feature source files. Allowed without a plan: .traffic-one/plan.md itself, .traffic-one/ project memory, root docs, legacy docs/, README.",
  "plan-guard :: plan-main-agent-gate": "Plan gate: .traffic-one/plan.md is missing on a new project in Low/main-agent mode. Do NOT call `run_subagent`, `Task`, `spawn_agent`, `task`, or another subagent tool. You are the architect in this thread: write `.traffic-one/plan.md` and required `.traffic-one/` project memory before root config, workspace scaffold, or feature-source writes; then resume the same ordered phases. Allowed without a plan: .traffic-one/plan.md itself, .traffic-one/ project memory, root docs, legacy docs/, README.",
  "plan-guard :: plan-opencode-queue-gate": "Plan gate: OpenCode is enabled — `.traffic-one/plan.md` must include the machine-readable `<!-- opencode-delegate:start -->` … `<!-- opencode-delegate:end -->` block with at least 3 runnable bounded units (`- id: <stable-unit-id> | role: frontend|backend|tester|docs | files: … | task: …`). Prose-only or incomplete OpenCode lists are ignored by `opencode_delegate_from_plan`. A rewrite may omit the block only after a queue was accepted for the current run — runtime then preserves and re-appends it. Concrete example of a runnable unit row:\n`<!-- opencode-delegate:start -->`\n`- id: seed-demo-data | role: backend | files: supabase/seed.sql | task: Seed the demo rows the plan data section describes`\n`<!-- opencode-delegate:end -->`",
  "plan-guard :: plan-opencode-queue-policy-gate": "Plan gate: OpenCode queue metadata is unsafe: {{ERRORS}}. Add stable unique `id` fields, exact `files` allowlists, and `depends` edges for overlapping areas.",
  "plan-guard :: plan-opencode-self-delegation-gate": "Plan gate: this run is already hosted by OpenCode/Kilo, so `.traffic-one/plan.md` must not include an OpenCode delegation queue or `opencode-delegate` marker. Remove the self-delegation block; implementer work runs directly on the current host.",
  "plan-guard :: registry-probe-gate": "Registry probe gate: do not query the npm registry (`npm view`/`show`/`info`/`outdated`, `pnpm view`, `yarn info`) to pick scaffold or dependency versions during new-project setup. Versions come from the active stack contract — install with the pinned ranges (`pnpm add <pkg>` resolves the latest matching minor/patch). Only an explicit user request for a newer major overrides a pin, recorded as an ADR in `.traffic-one/decisions/`.",
  "plan-guard :: reset-record-owner-gate": "Reset record gate: `.traffic-one/runs/.resets.json` is the project's record of every reset — how many have happened, and what each successor run inherited because of them. Traffic One's own recovery command is its only writer, and no agent, child or parent may create, edit, delete, truncate, move, replace or repair it through any channel. There is no correct run directory to write it under, so this refusal has no \"write it somewhere else\" remedy: it is not a run artifact and does not live inside a run. Erasing it USED to do two things — make the next reset free again, and drop the terminal model exhaustion a reset at or past the widening threshold handed the current run, which is what stops a role whose model is exhausted from respawning without the user's enable/retry answer. Both of those facts are now MIRRORED into the successor run's own `runs/<runId>/run.json` by the same reset that records them, and both readers take the record UNION that mirror with the user's enable/retry discharge ahead of both, so erasing THIS FILE ALONE moves neither decision: measured after a real `rm` through a spelling this fence does not see, the next reset is still priced at the height the ladder had reached and the inherited exhaustion still stands, and the user's answer still clears it in place. That is not the same claim as \"erasing the record no longer pays\", and it is deliberately not that claim — the mirror is a second copy inside the same project, so a command that takes the whole `runs/` directory takes both of them, and what the successor's `run.json` has instead of immunity is a fence of its own (`runtime-sidecar-owner-gate`) which was measured answering the three spellings below exactly as this fence answers them — the second copy is not better hidden, it is a different file, and being a different file is the whole of what it buys. READING it is allowed: `cat`, `head`, `tail`, `grep`, `jq`, `wc`, `sed -n` and an interpreter read of the path are all permitted. A command that names the record with any other verb is refused, because a file with no legitimate agent write has nothing to tell an unrecognised one apart from; so is a command that destroys a directory containing it (`rm -rf .traffic-one/runs`, `git clean -fdx`). A shell line that hides the path from static reading stood here as a five-member list — assembled by `cd`, a variable, `$(…)`, `eval`, or joined inside interpreter code — and the round that taught this fence to read the shell the way its sibling does falsified three of the five, so what follows is what was re-measured rather than what was inherited. REFUSED now, in all three project states: `cd .traffic-one/runs && rm -f .resets.json` and its `;` spelling, `R=.traffic-one/runs; rm -rf \"$R\"`, and an interpreter join that leaves any fragment spelling `.traffic-one` or this file's own name (`'.traffic-one/' + 'runs/.resets.json'`). STILL UNSEEN, which is a breach this gate cannot see rather than a route it permits, each one measured erasing this file in real bash at no refusal: what a substitution PRINTS (`rm -rf \"$(cat where)\"`); a `$( … )` body or a literal `eval` in the two states where no run directory exists for a sibling fence to answer first (`rm -rf \"$(echo .traffic-one/runs)\"` and `eval \"rm -rf .traffic-one/runs\"` are refused while a run directory is live and were measured NOT REFUSED once it is gone, which is when this file is the only thing left below `runs/`); and a join that splits both names through the middle (`'.tra' + 'ffic-one/runs/.res' + 'ets.json'`). That is what has been MEASURED to be unseen, in the states it was measured in, and not a proof that nothing else is. WHAT THOSE THREE NOW BUY is the other half of the same measurement, and it is the mirror above rather than any refusal that changed it: aimed at this file alone, they buy nothing — both decisions read the same before and after the erasure. Aimed at the whole `runs/` directory they still take both copies at no refusal, and the printed-substitution spelling was measured doing exactly that; aimed at either file alone they take one copy and the other still answers. So the unseen list above is unchanged, only the payoff of its narrowest use has moved, and a tree-wide erasure is recorded here as a known breach rather than implied to be closed. If the record itself is genuinely in the way, that is an operator decision made outside the agent, not a write to re-issue.",
  "plan-guard :: reviewer-structure-gate": "Reviewer gate: `APPROVED` is forbidden while the complete runtime structure report contains errors ({{FINDINGS}}). Review the compiled architecture and request fixes.",
  "plan-guard :: run-id-mismatch": "Run-id gate: this run's id (`currentRunId` in .traffic-one/.one.json) is `{{EXPECTED}}`, but this write targets run-id `{{WRONG}}`. The run-id is a plain epoch-millisecond number Traffic One mints for you — do NOT generate one with `date` (an ISO/UTC string like `2026-06-17T12-09-40Z` splits run state: assignments and digests land under a stray `.traffic-one/runs/{{WRONG}}/` that the run-team and OpenCode gates — keyed on `{{EXPECTED}}` — cannot see, blocking implementer spawns). Read `currentRunId` from .traffic-one/.one.json and write under `.traffic-one/runs/{{EXPECTED}}/` and `.traffic-one/digests/{{EXPECTED}}/` instead.",
  "plan-guard :: run-team-fallback-taken": "Run-team enforcement gate: `{{TARGET}}` is outside every runtime-compiled role scope and is already being written by `{{HOLDER}}` in this run. Coordinate so one existing work unit owns the path, or stop for semantic replanning and runtime regeneration of assignments before writing it.",
  "plan-guard :: run-team-not-subagent": "Run-team enforcement gate: this project was onboarded with `team.mode=\"subagents\"`, so feature-source and assigned build-artifact writes must come from a spawned Traffic One role session with a per-agent run claim, not {{ROLE}}. {{RECOVERY}} Do NOT fall back to delegating from inside a worker or rewriting team preferences.",
  "plan-guard :: run-team-quick-fix-contract": "Run-team enforcement gate: the quick-fix worker has no valid parent-published WorkUnitContract covering every requested output. Not covered by one: `{{TARGETS}}`. No maintenance or fallback write is allowed without the exact original contract and allowlist hash, and you cannot publish or widen that contract yourself — only the parent can, so retrying this write draws the same refusal. Write only the outputs your own published contract already names; if it names none of these, stop and write your digest with verdict `BLOCKED` listing exactly these paths, so the orchestrator can re-run parent preflight with a bounded runtime-owned contract that covers them.",
  "plan-guard :: run-team-runtime-allowlist-gap": "Run-team enforcement gate: STRUCT_ASSIGNMENT_ALLOWLIST_GAP — `{{TARGET}}` is outside `{{ROLE}}`'s immutable runtime-owned WorkUnitContract. No dynamic claim is allowed for a compiled run. Do NOT keep retrying this write, and do not move it to a path you do own. Report it in your digest instead: name `{{TARGET}}`, say it is in no role's allowlist, and set your verdict to `BLOCKED` (in a fix cycle, list it under `FIXES_FAILING` with this reason — that is the whole available action there, and it is a complete answer). Replanning ArchitectureInputV1 to compile a home for the path happens between runs, by the architect, never from inside this session.",
  "plan-guard :: run-team-runtime-contract-invalid": "Run-team enforcement gate: this run has CompiledArchitectureV1 but its current-run runtime assignments or VerificationContractV2 are missing, stale, or tampered. The write fails closed; repair/recompile this run and never borrow an assignments manifest from a sibling run.",
  "plan-guard :: run-team-scope-conflict": "Run-team enforcement gate: `{{TARGET}}` is in `{{OWNER}}`'s assigned scope for this run, not `{{ROLE}}`'s. Each subagent writes only within its runtime-compiled assignment in `.traffic-one/runs/<runId>/assignments.json`. Let the owning role write the target, or split the patch along the existing compiled work units.",
  "plan-guard :: run-team-shell": "Run-team enforcement gate: implementation writes via shell command (`>`, `>>`, `tee`, `cat <<`, `python -c`/`node -e` eval writes, `sed -i`, `rm`, `mv`, `cp`, `find -delete`) are denied because the hook cannot verify role ownership from a shell line — use the role-scoped Write/Edit tools instead. Run-state bookkeeping (heredocs targeting `.traffic-one/digests/`, `fix-cycles/`, or `runs/`) is exempt. Two shell shapes ARE verifiable and stay allowed: a single `cp`/`mv` importing one file from outside the project, and a single `rm <path>` (at most `-f`, never `-r`, no globs, one operand) removing a stray file that is present on disk, untracked, absent from the immutable baseline, and owned by nobody in the compiled contract — that is cleanup of your own by-product, not an implementation write.",
  "plan-guard :: run-team-unexpected": "Run-team enforcement gate: unexpected denial for {{ROLE}} writing `{{FILEPATH}}`. This is a gate bug — please report.",
  "plan-guard :: run-team-wrong-role": "Run-team enforcement gate: the active Traffic One role `{{ROLE}}` does not own `{{TARGETS}}`. Use the role that owns the path, or split the patch by role ownership.",
  "plan-guard :: runtime-assignments-owner-gate": "Runtime contract gate: `.traffic-one/runs/<runId>/assignments.json` is generated atomically from CompiledArchitectureV1 and VerificationContractV2. Agents and the parent may not create, edit, widen, or replace it; change ArchitectureInputV1 and re-run PLAN_READY compilation instead.",
  "plan-guard :: runtime-sidecar-owner-gate": "Runtime sidecar gate: `{{TARGET}}` is generated and atomically published by Traffic One runtime. Agents, children, and the parent may read it but may not create, edit, delete, widen, replace, or repair it. Write/Edit/apply_patch are refused outright. Shell is refused through two rules with OPPOSITE polarities, and the difference between them is the whole design. (1) THE READ RULE, asked of EVERY simple command of every shell line — not of a list of binaries — and asked wherever the path is spelled: at top level, inside a `bash -c`/`sh -lc`/`fish -c` body, inside a heredoc a shell or interpreter reads as code, and inside an interpreter eval body under `-e`/`-p`/`-r`/`--eval`/`eval`. Wherever the command text spells this path, EVERY CALL IN THE STATEMENT THAT SPELLS IT must be a recognised read, every open mode must be a read mode, and a path named in shell position rather than inside a call must be named by a verb that only reads. Everything else is refused, so a destructive spelling nobody has written down yet is refused for NOT BEING A READ rather than permitted for not being recognised: `zipfile.ZipFile(p,'w')`, `File.open(p, File::WRONLY|File::TRUNC)`, `Pathname.new(p).delete`, `path(p)->spew_utf8(\"\")`, `os.renames(p, …)`, a verb assembled at runtime (`fs['un'+'link'+'Sync']`), and equally `awk 'BEGIN{print \"\" > p}'`, `curl -o p`, `openssl enc -out p`, `ex -sc '%d|x' p` and an alias-escaped `rm` — none of which appears in any verb list this gate keeps. THE UNIT IS THE STATEMENT, NOT A PATH THROUGH IT, so a destruction BESIDE the occurrence is the same case as one above it: `list(map(lambda f: ZipFile(f,'w'), [p]))`, `[ZipFile(f,'w') for f in glob.glob(p)]`, `[q.unlink() for q in Path(<runs dir>).glob('*/run.json')]`, `Dir.glob(p).each { |f| Pathname.new(f).delete }`, `ZipFile(str(p),'w')`, `os.unlink(os.path.abspath(p))` and `console.log(unlinkSync(p))` are all refused, and a separator quoted to end the statement early (`ZipFile('; cat x'[0:0] + p,'w')`) does not shorten it. A MODE THAT IS NOT A RECOGNISED READ is refused for the same reason, including one bound to a variable (`m='w'; open(p,m)`), computed, or written as numeric flags (`os.open(p, 1|512|1024)`); `'r'`, `'rb'`, `'r:UTF-8'`, perl's `'<'`, `O_RDONLY`, `{read:true}` and no mode at all are reads. An INTERPOLATED path is refused through the directory its literal part names, so a template literal or f-string over `…/runs/<var>/run.json` and `rm -rf .traffic-one/runs/$OLD_RUN` are both refused even where the same deletion with the id spelled out is permitted housekeeping — spell the id if you mean a finished run; a path whose FIRST segment is interpolated is judged on what the REST of the literal spells, not on the part that is unreadable: `rm -rf \"$(pwd)/dist\"`, `rm -f \"$f\"`, `rm -rf \"$TMPDIR/scratch\"`, `mv \"$src\" dist/out.js` and `cp assets/logo.svg \"$dest\"` name no `.traffic-one` path at all and are not refused, while `rm -rf \"$PWD/.traffic-one/runs\"` and `rm -rf \"$ROOT/.traffic-one/runs\"` spell this tree in full under whatever root the variable holds and are refused, as are — ONE MEASURED SPELLING AT A TIME rather than a class asserted complete — the braced `\"${PWD}/…\"`, the `\"$(pwd)/…\"` one, one with a `./` in the middle, the unquoted `$PWD/…`, and each of those written with the closing quote after the VARIABLE instead of after the path (`\"$PWD\"/.traffic-one/runs`). THIS SENTENCE USED TO READ \"in any of its spellings\", naming the braced and `$(pwd)` forms as instances of a totality, and while it said so the quote-after-the-variable group was measured at NO REFUSAL, erasing every file under the runs tree including the reset ledger; it is a list of what was measured now for exactly that reason — including when that root would have turned out to be some other project's, which this gate cannot resolve and will not guess about. A CLOSING QUOTE FOLLOWED BY MORE PATH IS ONE WORD, as it is to the shell: `R=.traffic-one/runs; rm -f \"$R\"/<id>/run.json` is the sidecar and is refused, in that spelling, in the braced `\"${R}\"` spelling, and through a loop over `\"$R\"/*/run.json`. The head may be BOUND IN THE COMMAND or supplied by the SHELL, and until round 10 only the first was: `\"$PWD\"/.traffic-one/runs`, the `\"${PWD}\"`, `\"$(pwd)\"` and `\"$OLDPWD\"` versions of it, and `\".traffic-one\"/runs/../runs` each erased the whole runs tree at no refusal, because the word was SPLIT at the closing quote and the residue was then judged alone — `/.traffic-one/runs`, an absolute path resolving outside the project and naming nothing there. Every stage answered its own question correctly and the composition was wrong, which is why the unit is the shell WORD and both rules above assemble it the same way: a word from which any stage removed or failed to resolve a piece carries that fact into the judgement, and the remainder is not read as a path of its own. It used not to be — the remainder after the quote was read as an ABSOLUTE path, `/<id>` was adopted as the project root, and both rules above then ran against a directory that does not exist and found nothing, which is the worst shape a refusal can fail in: silent, permitting, and identical for every command whose path a variable holds. GLOB METACHARACTERS ARE NOT LITERAL EITHER, and they name whatever they match: `rm -rf .traffic-one/run?`, `.traffic-one/[r]uns`, `.traffic-one/[a-z]uns`, `.traffic-one/[!x]uns`, `.traffic-one/ru*`, `.traffic*/runs`, `.traffic-one/runs/1715*` and `.traffic-one/runs/*/run.jso?` are all refused, because Traffic One is handed the pattern and never the expansion. A pattern that CANNOT match this tree is not refused — `rm -rf .traffic-one/c?che` cleans the cache, `rm -rf *` does not reach a dotfile at all, and `rm -rf .traffic-one/runs/<a finished run's prefix>*` is the same housekeeping the id spelled out would be. A WORD IS ASSEMBLED BEFORE IT IS JUDGED, so shell-level quoting does not hide it: `.traffic-'one'/runs`, `\".traffic-one\"/runs`, `.traffic-one/'runs'` and the ANSI-C `$'.traffic-one/run\\x73'` are the same path and are refused as one. Quotes are removed only where removing them cannot change how the line splits, so `grep \"foo;bar\" {{TARGET}}` keeps its pattern and stays a read. A CHARACTER THAT DOES NOT DENOTE ITSELF MAKES THE WHOLE LITERAL UNREADABLE, and that is asked as an allowlist rather than as a list of metacharacters: a literal counts as the path it spells only when every character in it is one a shell hands through a word unchanged, and anything else — an expansion, a backtick, a BACKSLASH ESCAPE, a brace, a glob, a quote that survived assembly, a tilde at the head of the word — leaves it unresolved, in which case its longest complete directory prefix and what the `.traffic-one` remainder spells decide it. An unquoted backslash is resolved the way a shell resolves it, so `rm -rf .traffic\\-one/runs` is refused, as are `run\\s`, `\\runs`, `.\\traffic-one/runs` and the same escape inside a partly quoted word — five spellings that name exactly this tree to bash and erased it at no refusal until round 10; `\\` before a newline is a line continuation and disappears, while a backslash inside single quotes stays, because there it is data. `\\find . -name run.json -delete` is refused too, that escape having hidden the VERB rather than the path, and `find . -name \\*.json -delete` is refused because a `-name` pattern this gate cannot read may match anything rather than nothing. Asking it in this direction is the point: a metacharacter nobody here has written down leaves a literal unresolved on the day it arrives instead of the day someone destroys a run with it. An unreadable literal that does not spell this tree is not refused (`rm -rf ~/Downloads/tmp`, `rm -rf \"$TMPDIR/scratch\"`). A PARAMETER EXPANSION IS JUDGED ON THE VALUE IT CAN PRODUCE, and the bindings in the command are part of that value: names and expansions are resolved TOGETHER, so `runs=.traffic-one/runs; rm -rf \"${runs:-nosuch}\"` is refused on what `runs` holds and not permitted on the default word that never applies. Every operator that can yield this tree is covered — the defaults `:-`/`-`/`:=`/`=`, the alternates `:+`/`+`, the error forms `:?`/`?` (whose WORD is a message, but whose VALUE still deletes when the name is set), indirection `${!n}`, substrings `${v:off}`/`${v:off:len}`, suffix and prefix removal `${v%pat}`/`${v%%pat}`/`${v#pat}`/`${v##pat}`, replacement `${v/pat/rep}`/`${v//pat/rep}`, and a default nested inside a default. What an operator does NOT produce is not invented: `${#R}` is a LENGTH and never a path, `${R##*/.}` over `zz/.traffic-one/runs` leaves `traffic-one/runs`, which is a different directory, and `rm -rf \"${RUNS:?.traffic-one/runs}\"` with `RUNS` unset exits rather than deleting — all three permitted, all three ground-truthed as no-ops. Two rounds of history, because both were fail-open and both were structural: until round 8 only `:=` was refused and `:-` was not, its `-` being swallowed as a flag; round 8 then fixed defaults and bindings as two sequential textual rewrites, the first of which replaced the expansion with its default word and destroyed the name the second needed, which cost nine more whole-tree erasures at no refusal. One value model is the reason this list can be stated at all. An ESCAPED QUOTE inside a double-quoted `-c` body is unescaped before the body is judged, so a `bash -c` whose body wraps this path in backslash-escaped quotes is refused; the body used to arrive with those backslashes still attached, one character too long to match anything, and erased every sidecar at depth 1. THE VERB IS THE FIRST REAL COMMAND WORD, so shell grammar does not change any of the above: `if`/`then`/`for`/`while`/`case`/`do`/`!`, a leading `VAR=value`, and the transparent prefixes `env`/`nohup`/`sudo`/`command`/`timeout` are skipped to reach it; a SUBSHELL `( … )`, a brace group `{ …; }` and a command substitution `$( … )` are re-entered as command lists and their own contents judged; and `for f in <paths>; do … done` is judged with the binding RESOLVED, so a body that reads `\"$f\"` is permitted and one that deletes it is refused. (2) THE UNNAMED-DESTRUCTION RULE, for a command that names no runtime path, where there is no occurrence to judge a position of and a verb set is the only instrument available: `rm -rf` on the run directory or the project root, a `find` sweep whose action is not a recognised READ (`-delete`, or an `-exec`/`-execdir`/`xargs` action that is anything other than a reading verb — `rm`, `shred`, `truncate`, `gzip`, `sed -i`, `cp`, `tee`, and equally a WRAPPER whose body writes, `-exec sh -c '…rm…' _ {}`, because a `-c` body is re-entered as a command list rather than matched against a list of wrapper names; `-exec cat {}`, `-exec grep -l x {}`, `-exec sort {}` and `-exec sh -c 'cat \"$1\"' _ {}` are reads and stay permitted — the action's VERB is asked FIRST and its flags mean whatever that verb makes them mean, because an eval flag is an eval flag only on an INTERPRETER: `-exec jq -r`, `-exec grep -E`, `-exec grep -e`, `-exec grep -c`, `-exec wc -c`, `-exec head -c`, `-exec tail -c`, `-exec sort -r`, `xargs jq -r` and `xargs grep -c` are ordinary read sweeps and are permitted, while `-exec sh -c` and `-exec python3 -c` are re-entered as code; asking the flag before the verb refused all ten of those reads for one round, and the `-exec grep -l x {}` recorded here as permitted survived that round only because `l` happens not to be in the flag class), `dd of=`, `install`, `rsync`, `tar -x -C`, a replacing compressor, a named output (`sort -o`, `unzip -d`, `patch`), and any git spelling whose purpose is to override git's own refusal to clobber a locally modified tracked file: `clean -f`, `checkout`, `checkout -f`, `restore`, `switch --discard-changes`, `reset --hard`, `rm`, `mv`, `stash`, `checkout-index -f`, `read-tree -u`, `sparse-checkout set`, `submodule update --force`, and the `--abort` of `merge`/`rebase`/`cherry-pick`/`revert`/`am`. An ordinary `git merge`, `rebase`, `cherry-pick`, `revert` or `pull` is NOT refused, because git itself stops rather than overwrite a modified tracked file. This rule is fail-OPEN by construction — a verb nobody wrote down is admitted — which is why rule (1) exists and why it is the one that carries the unknown spellings. Reading is what stays permitted, and is the list that is maintained: `cat`, `head`, `tail`, `grep`, `rg`, `jq`, `wc`, `ls`, `stat`, `diff`, `cmp`, `sed -n`, `awk` with no output redirect in its program — a COMPARISON is not one, so `awk 'length($0) > 10 {print}'` reads while `awk '{print > \"out\"}'` does not — `sort` with no `-o`, `gzip -c`, `git log`/`git diff -- <path>`/`git show`, a `find` sweep whose action does not write, `readFileSync`, `open(p)` and `open(p,'r')`, `File.read`, `Path(p).read_text()`, `Pathname.new(p).read`, `file_get_contents`, `Deno.readTextFileSync`, perl's `open(my $fh, '<', p)`, stat fields and byte/text conversions over what was already read (`os.stat(p).st_size`, `statSync(p).mtimeMs`, `open(p,'rb').read().decode()`), path arithmetic (`os.path.join`, `basename`), and printing the path. WHAT THIS COSTS, because a fail-closed rule refuses reads it does not recognise and the refusals are real: a verb that reads this path without being on that list is refused anyway — `cp {{TARGET}} backup.json`, `dd if={{TARGET}}`, and `echo \"see {{TARGET}}\"` or `printf` of the path, which write nothing at all — `tar -cf backup.tgz <runs dir>` was listed here too and is measurably NOT refused, because creating an archive reads the tree and only `-x` writes it; a `find` action that hands the file to an INTERPRETER rather than to a verb (`-exec python3 -c '<code>' {}`) is refused whatever the code does, because the operand arrives as `sys.argv[1]` and there is nothing left to judge — spell the read as `-exec cat {}`; READING this path into an OUTPUT is refused whatever the reading verb is and wherever the output goes (`cat {{TARGET}} > out.txt`, `jq . {{TARGET}} > pretty.json`, `awk '{print}' {{TARGET}} > summary.txt`, `cat {{TARGET}} | tee out.txt`, `cat {{TARGET}} | jq . > pretty.json`), because the command as a whole writes and this path stands inside it — measured, all five, with no in-command remedy: read it in one command and write the result in the next; an interpolated ROOT that this gate cannot resolve is refused when the rest of the literal spells this tree (`rm -rf \"$ELSEWHERE/.traffic-one/runs\"`, `rm -rf \"dist/$X/.traffic-one/runs\"`), even when the root would have turned out to be somewhere else entirely; and an incomplete `for NAME in <paths>` with no `do … done` to bind into is refused because an unresolved binding is judged on nothing — including the GLOB spelling (`for f in .traffic-one/runs/*/run.json`), which this paragraph recorded as an unseen residue until globs became readable and which is now the same cost as the literal one; the path spelled OUTSIDE an interpreter body and read through it (`python3 -c 'print(open(sys.argv[1]).read())' {{TARGET}}`, `os.environ[\"RF\"]`) is refused because the occurrence sits in shell position under the verb `python3` — spell the path inside the body, or read it with `cat`; a single statement that reads this path AND calls something that is not a read, even about an unrelated path, is refused as one unit — use two commands; and `os.removedirs(<run dir>)` is refused although it would raise on a non-empty directory; METADATA on a sidecar is refused although it moves no content — `chmod 644 {{TARGET}}` and `touch -r package.json {{TARGET}}`, both ground-truthed as no-ops on the bytes — because a mode of `000` breaks the next publish as surely as a truncation and a `touch` of a MISSING sidecar fabricates one the runtime never wrote, so leave it alone and let the runtime rewrite it; and two CONVENIENCES around a run directory fall under the same operand-role limit that refuses `cp -r <runs dir> <backup>` — `ln -s <run dir> latest-run`, whose write is at the symlink and whose read is the run, and `mkdir -p <run dir>/debug`, which is idempotent on a directory that already exists. The symlink is the one of those two whose refusal is load-bearing rather than cheap, and it was measured: once the link exists, `rm -f latest-run/run.json`, `truncate -s 0 latest-run/run.json` and `find -L latest-run -name run.json -delete` are all `noop` and all destroy the sidecar, because a path through the link spells no `.traffic-one` literal for either rule to judge. Permitting the link would buy a laundering route for every command after it, so it stays refused; name the run directory itself when you want to reach it. A LITERAL THIS GATE CANNOT READ IS PRICED AT ITS READABLE PREFIX, so a name carrying a character the allowlist declines is refused inside `.traffic-one` even where it names nothing — a backslash-escaped space (`rm -rf .traffic-one/my\\ cache`), a semicolon or a parenthesis inside a quoted name — while a QUOTED space is data and is not (`rm -rf \".traffic-one/my cache\"` is permitted), and no such name outside `.traffic-one` is refused at all. A NAME IS SPLIT WHERE BASH SPLITS IT — on a SPACE, a TAB or a NEWLINE — and every other character JavaScript calls whitespace is DATA here for the same reason it is data to bash: the no-break space a browser paste leaves behind, a macOS Option-Space, the rest of the Unicode space block, and `\\v`, `\\f` and `\\r`, each ground-truthed with the word unquoted in operand position against a real bash, which forms ONE word from all of them. THIS CLAUSE USED TO READ \"as is a non-ASCII name\", promised beside the quoted-space one, and while it said so `rm -rf .traffic-one/runs<U+00A0>x` and its quoted spelling were both refused in every project state, against a ground truth of nothing moved, because a splitting class spelled as JavaScript's `\\s` cut the word at the no-break space and the remainder read as the runs ROOT — so the deny the developer read named the gate that owns `assignments.json`, which their command had nothing to do with. Both spellings are permitted now, and so are the other Unicode space characters measured beside them. The promise is the CLASS rather than that one character, and one member of the class is a KNOWN COST rather than a fix: `\\v`, `\\f` and `\\r` are data to bash but are not characters the allowlist above accepts as denoting themselves, so a `.traffic-one` name carrying one is priced at its readable prefix and refused in all three project states — by the rule this sentence opens with, rather than by an accident of a regex. FOUR REFUSALS THIS PARAGRAPH NEVER DISCLOSED ARE GONE, each ground-truthed as touching nothing: `xattr -l {{TARGET}}` LISTS extended attributes and is a read, where `-w`/`-d`/`-c` still refuse; `exec 3< {{TARGET}}; cat <&3` is a read through a file descriptor, where `3<>` opens for writing too and still refuses; `lsof +D <runs dir>` asks who holds a sidecar open, which is the first thing to ask when a publish looks stuck; and `rsync -an <runs dir> <backup>` is a DRY RUN that writes nothing by construction, while the real copy stays refused. An alias-escaped verb resolves to the verb it escapes in both directions, so `\\cat {{TARGET}}` reads and `\\rm -rf <runs dir>` does not. A refused dry run is the worst false refusal a fence over this tree can produce: it is the command reached for in order to destroy nothing — WHICH IS WHY BOTH OF THOSE SENTENCES ARE RECORDED HERE AS HAVING SHIPPED WHILE THE DRY RUN WAS STILL REFUSED. \"GONE\" was measured at THIS fence and at no other: the reset record's fence reads the same command text for its own file, it had no dry-run test at all, and it refused `rsync -an`, `rsync -a -n` and `rsync -a --dry-run` with `reset-record-owner-gate` in every project state named at the end of this paragraph, against a ground truth of nothing moved — so the sentence was true of the reader it was taken from and false of the product, because a refusal survives from ANY fence that can produce one and a permission has to be measured at all of them. All three spellings are permitted at both fences now, measured in all three states, while `rsync -a --delete <backup> <runs dir>` — which erases the reset record in real bash — is refused in all three. FINISHED-RUN HOUSEKEEPING IS ASYMMETRIC, which was true and undisclosed: deleting a finished run's DIRECTORY by its real id (`rm -rf .traffic-one/runs/<finished id>`) is permitted, while deleting one FILE inside that same directory (`rm -f .traffic-one/runs/<finished id>/run.json`) is refused — the directory question is answered by the run-rotation exemption and the file question by per-file ownership, and they do not meet. The exemption also needs the id to be a real one: an id of the shape the runtime mints (13 digits) that names no directory on disk, and any id that is not of that shape, are both refused as a run-id mismatch rather than treated as housekeeping. Remove the directory, or leave the run alone. WHAT REMAINS UNSEEN, which are breaches this gate cannot see rather than routes it permits — and this is what has been MEASURED to be unseen, not a proof that nothing else is, a distinction this paragraph used to get wrong by claiming the list \"is the whole of it\" while four escapes were open: a PATH for which no complete `.traffic-one` literal survives in the command text AND whose assembly is an INTERPRETER's rather than the shell's — concatenated inside code (`'.traffic' + '-one/…'`), computed (`chr(46)`), decoded (base64, hex), or produced as the OUTPUT of a substitution rather than spelled in it (`rm -rf \"$(cat where)\"`, `CMD=$(cat where); eval \"$CMD\"` — the body of a `$( … )` is judged, so `rm -rf \"$(echo <runs dir>)\"` is refused, but what a body PRINTS cannot be) — because each spelling is judged where it appears and following a value needs an interpreter rather than a position. FIVE entries stood in this list that measurement then found REFUSED, and they are named because a residue list that over-claims teaches the wrong lesson as surely as one that under-claims: a path joined over split segments (`os.path.join('.traffic-one','runs',…)`), one hidden behind `cd` (`cd .traffic-one/runs && rm -rf run-1`, its `;` and subshell spellings), one hidden behind a literal `eval` (`eval \"rm -rf <runs dir>\"`), and one BOUND TO A NAME in an INTERPRETER and destroyed through the name (`p=str('…/run.json'); zipfile.ZipFile(p,'w')`) are all refused. The fifth is the TILDE, which stood here as unseen with a note that the `$HOME` spelling of the same path IS refused — an inconsistency written down as a distinction, since `~` and `$HOME` denote one root. All four spellings are refused now (a bare `~` head, an unquoted `$HOME` one, a quoted one, and one with the closing quote after the variable), on the fail-closed ground this paragraph already gives for a root it cannot resolve, and the price is stated there: refusing another project's runs tree costs a rewording, permitting this one's costs the run. `~+` and `~-` were never HOME-relative to begin with — they are `$PWD` and `$OLDPWD` — so `rm -rf ~+/.traffic-one/runs` names THIS project under any HOME whatsoever, and it erased the whole runs tree at no refusal until round 10. A SHELL binding is resolved too — the `for` binding and an assignment, scalar or array — so a name bound to this tree and then deleted through `\"$d\"`, through a braced reference, or through an array subscript is refused, as is a name built from another name (`d=.traffic-one; e=\"$d/runs\"; rm -rf \"$e\"`), where until round 8 an ARRAY assignment was read as an expression grouping and destroyed the tree unseen; a BODY that never appears in the command text (arriving through a pipe instead of being spelled on the command line); and a PROJECT SCRIPT that does it (`npm run reset:state`), whose bytes are in package.json. `-c` NESTING IS NOT IN THAT LIST and used to be: \"more than four levels\" was recorded here and did not survive measurement — and neither did the figure that replaced it, which read \"a deletion is refused and a read is permitted at every depth from 0 to 12, in both quoting alternations\". That was narrower than it sounded and part of it was measured on a MALFORMED command: a driver that escapes the quotes of a double-quoted body but not its BACKSLASHES emits, from depth 3, a literal backslash and an early end of string, which is a different command and is what made a deep nest first look permitted and then look unseen. The figure has now been wrong three times and the driver was the cause every time, so it is stated PER SPELLING, from 63 commands each built, PRINTED, then run against a real bash over a real sidecar tree before any gate was asked. The three spellings are the double-quoted nest with quotes AND backslashes escaped (220 bytes at depth 6), the single-quoted nest whose body must re-quote itself as `'\"'\"'` (1538 bytes at depth 6, because each level roughly triples), and the mixed nest an agent actually types — single-quoted while the body holds no `'`, double-quoted once it does (158 bytes at depth 6). A DELETION IS REFUSED AT EVERY DEPTH FROM 0 TO 6 IN ALL THREE, measured twice over: 21 whole-tree deletions, each of which erased the tree completely when run (144B/12f to 0B/0f), and 21 deletions of a single named sidecar, each of which erased that file. The two arms answer different questions and both are worth having — a whole-tree delete is refused by the sibling gate that owns `assignments.json` and reaches it first, so only the single-file arm shows THIS gate's refusal surviving all six layers. A READ is permitted at every depth from 0 to 6 in the double-quoted and mixed spellings; in the `'\"'\"'` spelling it is permitted at depths 0 and 1 and REFUSED from depth 2 up, because a `-c` body capture ends at the first `'` and a re-quoted body is not one token. That is five refused reads, a cost in this paragraph's sense rather than a breach, and it is the only nesting cost measured. The double-quoted spelling was unseen from depth 2 up until round 8 closed five ground-truthed erasures, and the depth-5 and depth-6 READS are what hold the residual wrapper's body emptied — without it they are refused. A statement holding more than two hundred calls is NOT in that list — it is unresolved, and unresolved is refused. EVERY FIGURE ABOVE WAS MEASURED IN ONE PROJECT STATE, AND UNTIL NOW NONE OF THEM SAID SO: a project with a LIVE run directory, `.traffic-one/runs/<runId>/` holding real sidecars. The runtime passes through two others — a FINISHED run, its pointer set and its directory gone while an older run's directory is still on disk, and POST-RESET, `runs/` holding the reset record and nothing else — and what changes there is not this gate's own answer to a named sidecar, which is the same in all three, but WHICH FENCE ANSWERS AT ALL: a whole-tree spelling like `rm -rf .traffic-one/runs` is refused in the live state by the sibling that owns `assignments.json` and reaches it first, and in the other two by the reset record's fence, which is a different gate with different prose and, until the round that wrote this sentence, a quote-blind reader of its own. Two claims above are true only in the live state and are named rather than reworded, because their shape is the lesson: `rm -rf \"$(echo <runs dir>)\"` and `eval \"rm -rf <runs dir>\"` are refused with a run directory present and were measured NOT REFUSED in both of the other states, where each erases the whole tree including the reset record — which is exactly the state in which that record is the only thing left to destroy, and it is that record's own paragraph that names the routes to it that stay unseen. Of everything else stated above, what was re-priced across the three states did not move, and what was not carries the state it was taken in, which is the live one. A coverage figure with no project state in it is not a figure, and the escape that was found by asking for one had been live for as long as this paragraph had been priced without it. If you want `git stash` here, name the paths you actually mean — `git stash push -m wip src` is permitted. Otherwise change the semantic ArchitectureInputV1 or invoke the owning runtime transition instead.",
  "plan-guard :: scaffold-main-agent-plan-gate": "Plan gate: `.traffic-one/plan.md` is missing and this project is in Low/main-agent mode. Do NOT call `run_subagent` or another subagent tool. You are the architect in this thread: write the plan and required `.traffic-one/` project memory before root config or workspace scaffolding, then continue with the same ordered phases. Do not run `create-*` app scaffolders before the plan exists. Follow the runtime capability contract, not a frontend default: {{PROFILE_SUMMARY}}.",
  "plan-guard :: scaffold-plan-gate": "Plan gate: run the `senior-architect` subagent FIRST to produce `.traffic-one/plan.md` before scaffolding a new project. On Windsurf/Devin spawn it with `run_subagent` (profile `senior-architect`); the runtime derives the actual framework, roots, allowed roles, skills, and QA before implementation. Do not run `create-*` app scaffolders or invent layout conventions before the compiled plan exists. Runtime contract: {{PROFILE_SUMMARY}}.",
  "plan-guard :: scaffold-stack-gate": "Stack gate: this scaffolder conflicts with the runtime-derived capability contract ({{PROFILE_SUMMARY}}). Use `.traffic-one/plan.md` and `CompiledArchitectureV1` outputs for the detected framework and roots. If the requested stack differs, replan and correct capability evidence before scaffolding.",
  "plan-guard :: state-gate": "State gate: root .traffic-one/.one.json is missing or incomplete. Write the Traffic One state file with mode, stack, backend, realtime, confirmed, onboardingComplete, and confirmedAt before writing feature source. The .traffic-one/ folder is project memory, not the stack-selection state file.",
  "plan-guard :: state-mode-downgrade": "State mode gate: this project was onboarded as `new-project`; rewriting `.traffic-one/.one.json` to any other mode mid-run would disarm the architecture gates that mode selects. An UNRECOGNIZED `mode` counts — `workspace`, `brownfield`, anything the mode table does not name stands the same gates down as `existing-codebase` while the run's compiled architecture and verification contracts stay frozen against the old profile. An empty, absent or null `mode` is refused for a different reason: state normalization repairs it back to `new-project` on the next materialization pass, so the write does not survive as written and any gate reading the file before that pass reads a mode this project never declared. Mode changes go through onboarding, not a state-file edit. If the user explicitly wants this project treated as an existing codebase, re-run Traffic One onboarding.",
  "plan-guard :: supabase-local-stack-gate": "Supabase gate: the local Supabase stack is not part of this project's flow — do not run `supabase start`/`stop`, `supabase db reset`, `supabase functions serve`, or the `db:start`/`db:stop`/`db:reset`/`functions:serve` scripts, and do not boot Docker/OrbStack/Colima for them. Author `supabase/config.toml`, `supabase/migrations/*.sql`, and `supabase/functions/**` in the repo only; the user connects the real project (env keys, migration apply) through the traffic.io platform — every setup CTA links to `https://traffic.io/` — and the app must run in not-configured demo mode behind the EnvBanner until then. Verify SQL by review and committed migrations, not against a local database; `supabase db push --linked` stays a shipper-gated deploy action.",
  "plan-guard :: tester-no-test-evidence-disclosure": "Tester completion gate: this run settled with NO TEST EVIDENCE and the digest does not say so. The QA runner excused {{EXCUSED}} because this project declares no such command — no manifest script and no pinned language default — so nothing was measured for it and nothing here says the code is covered. That is allowed to settle, and it is not allowed to settle quietly: a reader of this digest must not have to open `report-v2.json` to discover that the test dimension was skipped rather than passed. Add a line to this digest containing the token `NO_TEST_EVIDENCE` and naming what was not measured (for example: \"NO_TEST_EVIDENCE — {{EXCUSED}} was excused: this project declares no test command, so no tests ran\"), then re-emit `TESTS_GREEN`. Do not add a placeholder test script to silence this; a script that runs nothing is worse than the honest absence.",
  "plan-guard :: tester-planned-module-gate": "Tester completion gate: `TESTS_GREEN` is forbidden while a compiled test module the tester owns is missing ({{MISSING}}). The complete structure scan blocks the reviewer's `APPROVED` on the same finding, so writing this verdict now spends a fix cycle to discover it. Create the module, run it, then re-emit `TESTS_GREEN`.",
  "plan-guard :: tester-qa-build-identity-mismatch": "Tester completion gate: the QA sweep validated a different application. Expected {{EXPECTED}}, observed {{OBSERVED}}. Stop the foreign server or bind a free strict port, then re-run before emitting `TESTS_GREEN`.",
  "plan-guard :: tester-qa-build-identity-missing": "Tester completion gate: do not write `TESTS_GREEN` when the report does not identify the build served over HTTP. Expected current builds: {{EXPECTED}}. Start the preview on a free strict port owned by this run, record the served fingerprint, and re-run the sweep.",
  "plan-guard :: tester-qa-v2-gate": "Tester completion gate: VerificationContractV2 rejected this verdict ({{ERROR}}). Dimensions: {{DIMENSIONS}}. Re-run only the failing dimension for uiImpact={{UI_IMPACT}}; a blocked environment is not `TESTS_GREEN`, and an `advisory-warning` is never the thing to fix. The sidecar is runtime evidence: produce it with the canonical runner — `node ~/.traffic-one/bin/qa-evidence-runner.cjs browser …` per the browser-qa skill, or `stack --run-id <id>` for no-browser contracts (the shim runs the plugin's `scripts/qa-evidence-runner.cjs`) — never by hand-editing `report-v2.json`. Hand-authoring it does not work: on a browser contract the runtime Playwright evidence is content-hashed against the report, and on a no-browser contract every excused check is cross-checked against the runner's own resolution record under `.traffic-one/runs/<id>/`, which is a runtime-owned sidecar no agent may write.",
  "plan-guard :: tester-stale-qa-gate": "Tester completion gate: do not write `TESTS_GREEN` on a stale QA report. The report was generated at {{GENERATED_AT}} but `{{DIGEST}}` was re-emitted at {{DIGEST_AT}}. Re-run QA against the current implementation and write fresh evidence before re-emitting `TESTS_GREEN`.",
  "plan-guard :: vanilla-extract-import": "vanilla-extract is no longer in the active stack — this file imports from the `@vanilla-extract` scope. The active stack styles with Tailwind and shadcn, so nothing installs that package or runs its build plugin, and the import has nothing to resolve to once the write lands. Re-issuing the file unchanged draws the same refusal — the rule reads the import specifier, so aliasing the package or importing it lazily does not satisfy it. Express the same styling with Tailwind utility classes and the shadcn primitives in `packages/ui/src/components/ui/`, editing the imports and the markup in this same file.",
  "plan-guard :: verification-contract-refresh-gate": "Verification refresh gate: `IMPLEMENTED` is forbidden because runtime could not rederive and atomically republish VerificationContractV2 from the immutable baseline ({{ERROR}}). Repair the semantic plan or runtime prerequisite and retry the same digest; stale UI-impact requirements never reach QA.",
  "plan-guard :: verification-contract-refresh-gate-approved": "Verification refresh gate: `APPROVED` is forbidden because {{ERROR}}. Re-read the newly published bootstrap/verification hash and repeat the review under the final risk contract.",
  "plan-guard :: verification-contract-refresh-gate-tests-green": "Verification refresh gate: `TESTS_GREEN` is forbidden because {{ERROR}}. Re-read the newly published verification hash, regenerate risk-proportional evidence, and retry the tester verdict.",
  "plan-guard :: verification-contract-scan-gate": "Verification contract gate: STRUCT_SCAN_INCOMPLETE ({{ERROR}}). Runtime could not derive the complete diff from the immutable baseline. `PLAN_READY` proceeds and the contract published below carries the truncation: `uiImpact` is pinned to the truncated-scan floor, so this run owes the browser evidence that floor requires. It cannot be CERTIFIED in this state, though — settlement re-derives the source identity from the same baseline and rejects the QA report as `scan-incomplete` whenever THAT scan is still truncated, no matter what evidence the tester gathers (it is the live re-derivation that decides, not the `scanComplete` field frozen into this contract; they agree only while the cause below is unfixed). Clear the cause named above (resolve the Git worktree, drop the symlink, narrow the generated/output roots the walk is counting) so the diff recompiles complete before the run reaches QA.",
  "plan-guard :: web-inline-style": "No static inline styles — this `.tsx` passes an inline style object whose every value is a plain string or numeric literal, which is exactly what a Tailwind utility class already expresses. A constant inline style leaves the design tokens behind: it cannot be themed through the HSL CSS variables, it carries no breakpoint or dark-mode variant, and it outranks any class a consumer later tries to override it with. Re-issuing the file unchanged draws the same refusal — the rule inspects the values inside the object rather than the element or the file, so moving the same literal object elsewhere does not satisfy it. Convert those entries to `className` utilities, reaching for a shadcn primitive where one exists, in this same file; an inline style stays allowed for a value computed at runtime, so a genuinely derived width or transform may remain.",
  "plan-guard :: websocket-location": "WebSocket construction belongs to the transport layer — this file constructs a WebSocket outside `packages/ws-client/` and `src/services/ws/`. A socket opened next to the UI is created and abandoned with the component that opened it, so reconnect, backoff, and fan-out to other subscribers have nowhere to live and every remount opens another connection. Re-issuing the file unchanged draws the same refusal — the rule reads the constructor call together with the path, so wrapping the call in a local helper does not satisfy it. Move the connection into `packages/ws-client/` or `src/services/ws/` and subscribe to it from here through a hook; if neither path is in your compiled allowlist, name this file and the transport module you need in your digest with verdict `BLOCKED`.",
  "session :: authoring-write-guard": "traffic-one — blocked: \"{{PATH}}\" is inside the Traffic One plugin source repository ({{ROOT}}). This repo is the plugin's own codebase, never a Traffic One project: do not create or touch `.traffic-one/**` here (no .one.json, manifest.json, one-mcp-report.json, runs/, rules/skills copies) and do not write generated AGENTS.md/CLAUDE.md project context into it. Shell commands referencing `.traffic-one` under this root are blocked unless clearly read-only — if your command was a read, re-run it in a form the classifier can verify (plain `grep`/`ls`/`cat` on absolute paths, no command substitution). Traffic One conventions inherited from a parent directory's AGENTS.md do not apply inside this repo. Continue the user's task with plain source edits.",
  "session :: workspace-member-unresolved-empty": "traffic-one — blocked: {{WORKSPACE}} is a Traffic One workspace that has registered no member projects at all, so {{PATHS}} sits in a container with no project in it. A workspace root holds no plan, no run state and no role claims — its MEMBERS are the projects — and registering one is a setup step no tool call can perform, so re-issuing this will produce this same refusal. Report it to the user as BLOCKED, naming {{WORKSPACE}} and its empty member registry, so they can run setup for the directory they want worked on.",
  "session :: workspace-member-unresolved-outside": "traffic-one — blocked: {{PATHS}} is inside the Traffic One workspace {{WORKSPACE}}, and belongs to no member project that workspace has registered. A workspace root is a CONTAINER of independent member projects, never a project itself — it holds no plan, no compiled architecture, no run state and no role claims — so no gate has anything at this level to judge this call against. The members it registered are: {{MEMBERS}}. Re-issue this call against exactly one of them: give it a path under that member, and if it is a shell command run it with that member directory as the working directory.",
  "session :: workspace-member-unresolved-registry": "traffic-one — blocked: {{WORKSPACE}} is a Traffic One workspace whose member registry could not be read — {{WHY}} — so {{PATHS}} cannot be attributed to a member and no gate can judge it. Traffic One's `.traffic-one/.one.json` is runtime-owned state: editing it by hand is itself denied, so there is nothing here for you to repair. Report this to the user as BLOCKED, quoting {{WORKSPACE}} and {{WHY}} verbatim so they can restore the registry or re-run setup.",
  "session :: workspace-member-unresolved-split": "traffic-one — blocked: this call spans {{COUNT}} members of the Traffic One workspace {{WORKSPACE}} at once — {{TOUCHED}} — through {{PATHS}}. Each member is an independent project with its own plan, run state and role claims, so a call crossing two of them has no single project to be judged against and no single owner to be attributed to; nothing here refuses the work, only the shape of the call. Split it into one call per member and issue them one at a time, starting with {{FIRST}}.",
};
